//! Every number the drawn iPod, the window's own size constants and §9.6's vertical column are
//! made of — declared exactly once.
//!
//! `docs/GUI.md` §16.9 is the rule this file exists to keep: *the constants live in one place, the
//! tests read them, and a claim without a check is deleted rather than left standing.* The markup
//! gets these values through a `.slint` file generated by `build.rs`; the tests read this module
//! directly. So the test reads what the markup reads, and the hand-copied block that used to sit in
//! `main.rs`'s test module — with a comment admitting it was a known hole, and with a **stale copy
//! of a corrected ratio** in it — is gone.
//!
//! ── Two constraints on this file, both load-bearing ──────────────────────────────────────────
//!
//! **No `use` of anything outside `core` / `std`, and no inner attributes.** `build.rs` compiles
//! this same file (`#[path = "src/geometry.rs"] mod geometry;`), and a build script can see only
//! its own build-dependencies. A `use slint::…` here stops the build script compiling, and the
//! error points at `build.rs` rather than at the line that caused it.
//!
//! **Nothing here is persisted.** `k`, the measured client height and the too-short boolean are
//! recomputed every launch. A remembered `k` would survive a move from a 2× display to a 1× one and
//! put §9.6's shelf — the row carrying `write_target()` — below the bottom edge, which is the exact
//! failure §16.1 describes. No key for any of this appears in `settings.txt`, ever.

/// How a constant is rendered into Slint.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Unit {
    /// A fraction of `body-height`. Emitted as `out property <float>`.
    Ratio,
    /// A logical pixel length. Emitted as `out property <length>` with a `px` suffix.
    Px,
}

/// Defines each constant once, and **simultaneously builds the emit table**, so there is no second
/// list of "which constants exist" to fall out of step with the first.
macro_rules! geometry {
    ($( $(#[$doc:meta])* $name:ident : $unit:ident = $value:expr ; )*) => {
        $( $(#[$doc])* pub const $name: f64 = $value; )*

        /// Every constant, in declaration order: the Rust name, how to render it, and its value.
        ///
        /// Built by the same macro invocation that declares them, so a constant cannot be defined
        /// and then silently not emitted.
        pub const ALL: &[(&str, Unit, f64)] =
            &[ $( (stringify!($name), Unit::$unit, $name) ),* ];
    };
}

geometry! {
    // ── §6.6 the drawn device: every ratio is a fraction of body height ──
    //
    // Measured from Rockbox's own scale drawing of this device, except the screen's *size*, which
    // §6.6 took off the drawing: the drawing governs where the screen sits, the hardware governs
    // how big it is. `SCREEN_W` / `SCREEN_H` is exactly 4:3 by construction, which is the one rule
    // this project will not bend.

    /// Body width as a fraction of body height. 104.1 mm × 61.6 mm.
    BODY_ASPECT:      Ratio = 0.5917;
    /// 50.8 mm / 104.1 mm — the hardware's own width, not the drawing's.
    SCREEN_W:         Ratio = 0.48799;
    /// 38.1 mm / 104.1 mm. `SCREEN_W / SCREEN_H` is 4:3 to within 1e-5.
    SCREEN_H:         Ratio = 0.36599;
    /// Where the drawing puts the top of the active area. Equals [`left_inset`] to 0.00065.
    SCREEN_TOP:       Ratio = 0.0525;
    /// The black glass overhang, and it is the same on **all four** sides:
    /// `0.51999 − 0.48799 = 0.032` and `0.39799 − 0.36599 = 0.032`, so `0.016` per side.
    BEZEL_RATIO:      Ratio = 0.016;
    GLASS_CORNER_R:   Ratio = 0.008;
    CORNER_R:         Ratio = 0.0501;
    WHEEL_D:          Ratio = 0.3675;
    WHEEL_TOP:        Ratio = 0.5215;
    CENTRE_D:         Ratio = 0.1228;
    MARK_INSET:       Ratio = 0.024;
    MARK_W:           Ratio = 0.036;
    MARK_H:           Ratio = 0.024;
    PLAY_W:           Ratio = 0.040;
    MENU_TOP:         Ratio = 0.024;
    MENU_SIZE:        Ratio = 0.026;
    MENU_TRACK:       Ratio = 0.003;
    HOLD_W:           Ratio = 0.100;
    HOLD_H:           Ratio = 0.024;
    HOLD_INSET:       Ratio = 0.055;

    // ── §6.6 the physical hero ──

    /// **The body height at which one framebuffer pixel is one device pixel**, in PHYSICAL px.
    ///
    /// `320 / SCREEN_W` = 655.7511424414434, and `240 / SCREEN_H` = 655.7556 — the same number to
    /// four figures, which is the tell that the well is 4:3. Written as the quotient rather than as
    /// a typed 655.751 so that a re-measured `SCREEN_W` moves it.
    HERO_PHYS_1X:     Px = 320.0 / SCREEN_W;

    // ── §9.6 the vertical budget, logical px ──

    /// The only elastic term in the column; it absorbs all slack.
    MARGIN_TOP:       Px = 24.0;
    MARGIN_TOP_MIN:   Px = 0.0;
    /// The cradle outline is offset **outward** by this much.
    CRADLE_OVERHANG:  Px = 10.0;
    /// The focused state adds 2 px more, 4 px outside the overhang.
    FOCUS_GAP:        Px = 6.0;
    /// Overhang + focus ring, one side. Appears **twice** in the column — above the body as well as
    /// below it, which is the term the previous revision listed once and lost off the top edge.
    CRADLE_BAND:      Px = CRADLE_OVERHANG + FOCUS_GAP;
    GAP_1:            Px = 6.0;
    GAP_1_MIN:        Px = 2.0;
    /// §12.3's boot rule — *"a 4 px indeterminate rule that does not animate would be
    /// acceptable"*, and this is the determinate one it is the ceiling for.
    ///
    /// **It costs nothing in the vertical budget and that is why it is where it is.** The band
    /// between the body's bottom edge and the cradle's bottom ring line is
    /// `CRADLE_BAND − FOCUS_GAP − FOCUS_RING_W` = 16 − 6 − 2 = **8 px** of clear fixture that
    /// already exists at every size, so the rule sits inside it with [`BOOT_RULE_GAP`] above and
    /// 2 px of clearance below the ring. Nothing in `CHROME_MIN` or `CHROME_PREF` moves, which is
    /// what stops a progress indication costing a display class (§9.6).
    ///
    /// **On the cradle, not on the device** — principle 3. It is UI state, and UI state is drawn
    /// on the fixture; a 4 px bar across the bottom of the iPod's own case would be the one thing
    /// §6.5 and §7.3 exist to prevent.
    BOOT_RULE_H:      Px = 4.0;
    /// Between the body's bottom edge and the boot rule. 8 px of band, 2 above and 2 below.
    BOOT_RULE_GAP:    Px = 2.0;
    CRADLE_LABEL:     Px = 24.0;
    GAP_2:            Px = 16.0;
    GAP_2_MIN:        Px = 8.0;
    /// Flush to the bottom edge, three rows.
    SHELF:            Px = 88.0;
    /// Everything in the column that is not the body, at minimum. Declared, then derived from the
    /// terms by `the_column_terms_sum_to_the_declared_chrome`.
    CHROME_MIN:       Px = 154.0;
    /// Everything in the column that is not the body, preferred.
    CHROME_PREF:      Px = 190.0;

    // ── §9.6 the horizontal budget, logical px ──

    DRAWER_W:         Px = 420.0;
    /// 20 each side of the well.
    WELL_AIR:         Px = 20.0;

    // ── §5's primitives, §6.3's space scale applied, and §7.5's furniture ──
    //
    // Everything below is a **drawer or Rail** measurement. They are geometry in exactly the sense
    // item 9 means it — a position or a size the markup would otherwise carry as a literal — so
    // they live here and `no_geometry_literal_survives_in_the_markup` is what keeps them here.
    //
    // Two of them are numbers the design does not state; both say so in their own doc comment, and
    // both are derived rather than typed, so re-measuring the term they are built from moves them.

    /// §5: *a Row is one thing, on a line, 44 px.* The rhythm every drawer page is made of.
    ROW_H:            Px = 44.0;
    /// §5: the value column starts here, measured from the row's leading edge — so the value has
    /// one x on every page rather than one per page.
    ROW_VALUE_X:      Px = 232.0;
    /// §6.3's drawer page margin. The same 24 as `Metric.s5`, and the duplication is bounded and
    /// asserted — `the_row_value_column_fits_the_drawer` reads `s5` out of `tokens.slint` as text.
    PAGE_MARGIN:      Px = 24.0;
    /// What is left for the value. **Written as the expression**, so a re-measured drawer moves it
    /// rather than leaving two numbers to disagree.
    ROW_VALUE_W:      Px = DRAWER_W - 2.0 * PAGE_MARGIN - ROW_VALUE_X;
    /// One Row tall, so the header and the rows under it share a rhythm.
    ///
    /// **The design states no number.** §11.2's *"≈ 60"* covers the page header **and** the group
    /// rules together — an approximation inside a total, not a declaration — so this is derived
    /// from the Row rather than read off that. It is load-bearing: `the_drawer_fits_its_own_
    /// furniture_at_the_window_minimum` is built on it. Look at it on screen before trusting it.
    DRAWER_HEADER_H:  Px = ROW_H;
    /// §10.1's three-line ledger, pinned: `3 × LINE_LABEL` plus 12 above and 12 below.
    ///
    /// **The design states no number** either; this is the derivation, not a measurement. Same
    /// caveat as [`DRAWER_HEADER_H`].
    WORK_FOOTER_H:    Px = 3.0 * LINE_LABEL + 2.0 * FOOTER_PAD;
    /// The air above and below a **pinned footer**, one side.
    ///
    /// Extracted from [`WORK_FOOTER_H`]'s own `+ 12.0 + 12.0`, which was the same number typed
    /// twice on one line. §11.2's `Create` is the second pinned footer this program has, and two
    /// footers deriving their padding from two literals is how the two come to sit at different
    /// heights on two pages that are supposed to share a rhythm. One number, two readers.
    FOOTER_PAD:       Px = 12.0;
    /// §11.2's pinned `Create` row — a Row with [`FOOTER_PAD`] above and below it.
    ///
    /// **Outside the Flickable** (§16.11: *a primary action that scrolls away is a primary action
    /// you hunt for*), which is why it is a footer height rather than a row inside a page.
    PRIMARY_FOOTER_H: Px = ROW_H + 2.0 * FOOTER_PAD;
    /// The least body a drawer page may be given — two Rows, which is a heading and one thing.
    DRAWER_MIN_BODY:  Px = 2.0 * ROW_H;
    /// §4: *max 3 levels deep.* A `Ratio` so it emits as `float` and compares against a depth with
    /// no unit on it.
    DRAWER_MAX_DEPTH: Ratio = 3.0;
    /// One slot per level, plus a blank at each end — because `lively` is `ease-out-back` and
    /// overshoots by design, and without the blanks an overshoot at either end slides a hole into
    /// view. They cost nothing.
    DRAWER_STRIP_SLOTS: Ratio = DRAWER_MAX_DEPTH + 3.0;
    /// §7.5's drawer handle, on the well's trailing edge so it rides the push.
    HANDLE_W:         Px = 12.0;
    HANDLE_H:         Px = 96.0;
    /// §5: *a 34 px two-line reason slot, reserved whether or not it is filled.* That reservation
    /// is what makes principle 2 mechanical — the control does not change height when it is refused.
    FIELD_REASON:     Px = 34.0;
    /// §7.3's focus ring, reused by every `Pressable`. Two, not one: a one-device-pixel hairline is
    /// a border, and a focus ring has to be visible against the material as well as against the
    /// page.
    FOCUS_RING_W:     Px = 2.0;
    /// §10.1's ghost: the drawn iPod, in `Colour::Unspecified`, at 45 % — **an iPod that has not
    /// been decided yet**, which is what an empty bench has.
    ///
    /// A `Ratio` rather than a `Px` because it is a fraction and not a length; the `Unit` table has
    /// no third kind and does not need one, exactly as [`DRAWER_MAX_DEPTH`] is a `Ratio` for being
    /// a count. It emits `out property <float> ghost-opacity: 0.45;`.
    ///
    /// **It is a number about the BODY and not about the glass**, and that is measured rather than
    /// argued: Slint composites an `opacity` over the whole subtree at once, so putting this on the
    /// device as a whole lifts the `#08080a` glass toward the well and drops it under the 3:1 bar
    /// `the_cradle_colours_clear_three_to_one_against_the_well` already holds everything on that
    /// surface to. §10.1's own next sentence is *the glass is dark* and §12.2 gives `Off` a
    /// `#08080a` glass; one `opacity` cannot honour both, and the sentence with a number behind it
    /// wins. So the markup puts this on the shell and declares the glass after it.
    ///
    /// **Nothing in markup may type this number** — `GEOMETRY_PROPS` does not list `opacity`,
    /// because four cosmetic opacities in `ipod.slint` and one in `primitives.slint` are literals
    /// that belong where they are; `no_opacity_literal_outside_the_cosmetic_set` is the narrower
    /// sweep that keeps 0.45 out instead.
    GHOST_OPACITY:    Ratio = 0.45;
    /// §7.5's 3 px accent bar. **One constant** — the shelf's bar and the Rail's bar are the same
    /// bar at two sizes of surface, and two names for one number is how they come to disagree.
    PROGRESS_H:       Px = 3.0;
    /// The Rail's verb column, so a plan reads as a column rather than as a paragraph.
    ///
    /// **64 was the value nobody had measured, and it would have elided.** Every other constant here
    /// is quoted from the design or derived from one that is. The longest verb is `synthesise` — ten
    /// characters, `ui/rail.slint`'s own six-verb list — and it appears at first-run step 1, the
    /// first thing a new user ever sees this program do. So if it elides, it elides there.
    ///
    /// **MEASURED 2026-08-21, macOS 27.0, scale 2**: `synthesise` draws **67.0 logical px** at
    /// `BODY_SIZE` 14 in the face this platform gives a `Text` with no `font-family` binding. So
    /// 64 was three pixels short and this column is comfortable. The recipe is
    /// `IPOD_LAYOUT=1 ipod-emulator`, whose `verb` line prints it — the measurement is taken by a
    /// `Text` in `ui/window.slint` (`verb-probe`, `visible: false`, outside every layout) and read
    /// back through `MainWindow.verb-width`, because Slint 1.17 exposes no Rust-side way to measure
    /// text and the only place the answer exists is the renderer.
    /// `the_verb_column_holds_the_verb_this_platform_draws` in `tests/startup_fit.rs` asserts it
    /// against the real binary on a real display.
    ///
    /// **The budget**: `10 chars × BODY_SIZE 14 px × BODY_ADVANCE 0.62 = 86.8`, rounded up to a
    /// whole logical pixel. Written as a round number rather than as that product because a column
    /// width is a whole number of pixels and `86.80000000000001` is what the product actually is;
    /// `the_rail_verb_column_holds_the_longest_verb` is what re-derives it, out of the verb list in
    /// `ui/rail.slint` rather than out of a second copy here, so a seventh and longer verb fails
    /// this rather than eliding in the drawer.
    ///
    /// **[`BODY_ADVANCE`] stays the conservative 0.62 rather than the measured 0.479**, and that is
    /// deliberate: one platform's face is not every platform's, and the budget is also what derives
    /// [`CRADLE_LABEL_MAX_CHARS`] — where being generous would let a longer sentence through onto a
    /// row that then elides. A budget above the measurement errs toward columns that are too wide
    /// and sentences that are too short, which is the safe direction for both.
    ///
    /// **It does not squeeze the Rail.** The drawer body is `DRAWER_W − 2 × PAGE_MARGIN` = 372;
    /// the entry row is a 16 px marker, `s2`, this column, `s2`, then `what` — which carries
    /// `horizontal-stretch: 1; min-width: 0px;` (`ui/rail.slint:171-172`) — and a measure. The 24
    /// px comes out of `what`.
    RAIL_VERB_W:      Px = 88.0;
    /// §9.3's next-step column — the floor under `Retry` / `Provide a file…`,
    /// `Choose a folder…` / `Cancel`, `Provide a file…` / `Copy the details`.
    ///
    /// **The same defect [`PARTS_VERB_W`] was written for, one surface over, and photographed
    /// before it was believed.** The two halves of a failure's next-step row are
    /// `horizontal-stretch: 1` with **no floor at all**, and a `Text` with `overflow: elide` reports
    /// a minimum of one ellipsis — so the row shrank by stretch and the half whose reason is a
    /// sentence kept its width at the expense of the half whose label is a word. Measured off
    /// `_out/gui/work-failed.png`, before this constant existed: `Class::Network` drew a live
    /// **`Retry`** in **98 px** with its own consequence elided to *Runs this step …*, beside its
    /// sibling in 194; `Class::Verification` after one retry drew `Copy the details` in **114**
    /// beside a sibling in 178. Neither pair is half and half, and neither half is the one the row
    /// is about. (The sibling in both was `Provide the file yourself…`, which the same measurement
    /// then shortened to `Provide a file…` — a label does not fit half a block either.)
    ///
    /// **It is the half-share, so two of them and the gutter are the row exactly.** The Rail is
    /// [`REFUSAL_MEASURE`] 372 wide (`ui/work.slint`'s body pads by `Metric.s5`, which is
    /// [`PAGE_MARGIN`]); the failure block pads by `Metric.s3` on each side, leaving 348; the two
    /// halves are separated by `Metric.s2`. `(372 − 24 − 8) / 2 = 170`, and `170 + 8 + 170` is 348 —
    /// so under any pressure at all both halves are exactly 170 and neither can be squeezed by its
    /// sibling. A row with one next step still stretches to the whole 348.
    ///
    /// Written as the expression so a re-decided page margin moves it. The two literals are
    /// `Metric.s3` and `Metric.s2` off §6.3's closed space scale; `the_next_step_column_is_the_half_
    /// share_of_the_row_it_is_in` reads both out of `ui/tokens.slint` as text, which is the
    /// arrangement [`PAGE_MARGIN`] already has with `s5`.
    RAIL_NEXT_W:      Px = (REFUSAL_MEASURE - 2.0 * 12.0 - 8.0) / 2.0;
    /// §11.4's group-verb column — the floor under `Add a dump…` / `Synthesise…`, `Fetch…` /
    /// `Provide…`, `Build…`, `Discard`.
    ///
    /// **A group verb elided to `F…`, and [`RAIL_VERB_W`] was not the reason.** The two verbs share
    /// one `HorizontalLayout`, each carrying `horizontal-stretch: 1` and nothing else; a `Text` with
    /// `overflow: elide` reports a minimum width of one ellipsis
    /// (`i-slint-core-1.17.1/items/text.rs:656-659`), so each control's floor was about four pixels.
    /// When the row cannot hold both preferred widths the solver shrinks **by stretch**, which for
    /// two equal stretches is the same number of pixels off each
    /// (`i-slint-core-1.17.1/layout.rs:190-251`). **All four numbers measured**: the row holds
    /// `DRAWER_W − 2 × PAGE_MARGIN − Metric.s3` = 360; `Provide…`'s disabled half prefers **411**,
    /// which is its reason drawn as one line at `Metric.label-size`, not its label; `Fetch…`'s
    /// prefers **52**, which is its label. 463 into 360 is 103 px to shed and each half is asked
    /// for 51.5 — so the one that had 52 hit its ellipsis floor and drew `F…` while the one that had
    /// 411 paid the rest. **The sibling's reason was the cause and the missing floor was the
    /// defect** — a wider Rail column would have changed nothing.
    ///
    /// **MEASURED 2026-08-22, macOS 27.0**, by `group-verb-probe` in `ui/window.slint` at
    /// `BODY_SIZE` 14 and `Metric.weight-strong` 600, read back through
    /// `MainWindow.group-verb-width`: `Add a dump…` **95 px**, `Synthesise…` 88, `Provide…` 66,
    /// `Fetch…` 52, `Discard` 52, `Build…` 49. **The widest is not the longest** — the first two are
    /// both eleven characters — which is the whole reason this was measured rather than counted.
    ///
    /// **The budget**: `11 chars × BODY_SIZE 14 px × BODY_ADVANCE 0.62 = 95.48`, plus `Metric.s2` 8
    /// of margin, rounded up to a whole logical pixel — the same shape [`FIELD_LABEL_W`] is written
    /// in. The margin is not decoration: [`BODY_ADVANCE`] is generous at `weight-body`, where the
    /// measured advance is 0.479, and is **not** generous at `weight-strong`, where this
    /// measurement makes it `95 / 11 / 14 = 0.617` against a 0.62 budget. A column derived from the
    /// budget alone would clear this platform's face by half a pixel and a one-percent wider face by
    /// nothing at all, which is a coincidence rather than a column.
    ///
    /// **104 was enough for the label and not for the reason, and the picture is what said so.**
    /// The floor above holds the verb; it does not hold the half of the row the verb's *refusal* is
    /// drawn in, because 104 is not the half-share and the shrink is free to take the difference.
    /// Measured off `_out/gui/parts.png` with every reason already cut to
    /// `REASON_MEASURE`: **Apple firmware** drew `no file picker in this build` as
    /// *no file picker in this …* while **Bootloaders** drew the same string whole, and the only
    /// difference between the two rows is the `mono` escape hatch under the *other* half —
    /// `ipod-boot firmware get <family>` against `ipod-boot rockbox-install`. A wider sibling took
    /// the pixels, exactly as `Provide…`'s reason took them from `Fetch…` before this constant
    /// existed; the fix is the same one [`RAIL_NEXT_W`] carries, which is that the floor must be the
    /// share and not merely enough.
    ///
    /// **So it is the half-share, and two of them and the gutter are the row exactly.** The drawer
    /// body is [`REFUSAL_MEASURE`] 372 and the two verbs are separated by `Metric.s3`:
    /// `(372 − 12) / 2 = 180`, and `180 + 12 + 180` is 372. Under any pressure at all both halves
    /// are exactly 180, a lone verb still stretches to the whole 372, and every reason clears its
    /// column by 34 px. `the_group_verb_column_holds_every_verb_this_page_draws` re-derives the
    /// widest verb out of `parts::Action::ALL` rather than out of a second copy here, so a seventh
    /// and longer verb fails that rather than eliding on the page.
    PARTS_VERB_W:     Px = (REFUSAL_MEASURE - 12.0) / 2.0;
    /// §6.2's `label` line box.
    ///
    /// **`Text` has no `line-height` in Slint 1.17** — the property does not exist — so a line box
    /// is a container height and that is what this is. The other five roles get theirs when they
    /// get a use site.
    LINE_LABEL:       Px = 16.0;
    /// §6.2's `title` line box — *20 / 26*. The shelf's first row is its use site.
    ///
    /// It lived in `ui/bench.slint` as `Metric.title-size + Metric.s3 / 2` while `src/geometry.rs`
    /// had a different owner; the stated retirement condition was *when `geometry.rs` declares it*,
    /// and this is that. Written as the number the design states, checked against the type scale by
    /// `the_shelf_line_boxes_are_the_type_scales`.
    LINE_TITLE:       Px = 26.0;
    /// §6.2's `body` line box — *14 / 20*. The shelf's second row.
    LINE_BODY:        Px = 20.0;
    /// §9.5's pane: the measure its two sentences are set at, and the width of its primary Row.
    ///
    /// **Derived, never typed.** The narrowest well this window can produce is
    /// `MIN_WIDTH − DRAWER_W` — the declared minimum width with the drawer open, which is the one
    /// case §9.6 says *the drawer never widens the window* about — and §7.1 gives the well
    /// [`WELL_AIR`] a side. So this is the widest measure that cannot overflow at any size the
    /// window allows, and `the_short_pane_fits_the_narrowest_well_this_window_has` is what holds
    /// it to that. It does not grow with the well: a sentence set across 1140 px is a sentence
    /// nobody can read a second line of (§6.2).
    SHORT_MEASURE:    Px = MIN_WIDTH - DRAWER_W - 2.0 * WELL_AIR;
    /// §7.3's clamp marks: `3 × 28` at the body's mid-height, one on either side of the cradle.
    CLAMP_W:          Px = 3.0;
    CLAMP_H:          Px = 28.0;
    /// §11.2: *THE VERDICT — 54 px, always reserved.* Emitted now so the Composer's own fit can be
    /// checked before the Composer is written.
    VERDICT_H:        Px = 54.0;

    // ── §11.1's Field, and why it is not a Row ──────────────────────────────────────────────────
    //
    // §5's fifth primitive has three cells rather than a Row's two, and its own column rule. The
    // reason is measured rather than preferred: a 16-hex-digit GUID at `Metric.mono-size` 13 is
    // `16 × 13 × BODY_ADVANCE` = 129 px, and a Row's drawable value width is `ROW_VALUE_W` 140 less
    // a 16 px chevron gutter = 124. The identity values would elide in a Row and do not in a Field.

    /// The `Field`'s leading label cell, in [`RAIL_VERB_W`]'s shape rather than in the design's.
    ///
    /// **The design states no number**; this is the budget, and it is derived. The longest label in
    /// the column is `Bootloader` — ten characters — so
    /// `10 × BODY_SIZE 14 × BODY_ADVANCE 0.62 = 86.8`, plus `Metric.s2` of gutter, rounded up to a
    /// whole logical pixel. A column width is a whole number of pixels, so it is written as a round
    /// number rather than as the product, exactly as [`RAIL_VERB_W`] is.
    ///
    /// [`BODY_ADVANCE`] stays the conservative 0.62 rather than the measured 0.479 for the reason
    /// its own doc gives: a budget above the measurement errs toward columns that are too wide,
    /// which is the safe direction for a column.
    FIELD_LABEL_W:    Px = 96.0;
    /// The `Field`'s trailing control cell — `Show` / `Hide`, four characters.
    ///
    /// `4 × BODY_SIZE 14 × BODY_ADVANCE 0.62 = 34.7`, plus `Metric.s3` either side = 58.7, rounded
    /// up to the next value that leaves [`FIELD_VALUE_W`] a round figure.
    ///
    /// **`Show` and `Hide` are the same width by construction** — both four characters — so the
    /// cell does not change size when the mask comes off, which is §11.2's *pressing `Show` changes
    /// no width and moves nothing*.
    FIELD_ACTION_W:   Px = 64.0;
    /// What is left for the value. **Written as the expression**, like [`ROW_VALUE_W`], so a
    /// re-measured drawer or label column moves it rather than leaving two numbers to disagree.
    ///
    /// 212 px holds both identifiers with room: a 16-hex-digit GUID is 129 at `mono-size` 13 and an
    /// 11-character serial is 89. That is the whole argument for §5's `Field` being its own
    /// primitive rather than a `Row` with an editable value.
    FIELD_VALUE_W:    Px = DRAWER_W - 2.0 * PAGE_MARGIN - FIELD_LABEL_W - FIELD_ACTION_W;
    /// §6.2's `mono` line box — *13 / 18*. The sibling of [`LINE_LABEL`] 16 and [`LINE_BODY`] 20.
    ///
    /// New because §11.4's `Settings file` sub-line and §11.2's identity values are the first mono
    /// line boxes to appear inside a drawer row. `Text` has no `line-height` in Slint 1.17, so a
    /// line box is a container height — the same arrangement [`LINE_LABEL`] has.
    LINE_MONO:        Px = 18.0;

    // ── §11.2's plan region, and §11.3's refusal ────────────────────────────────────────────────

    /// One step of the plan on the Composer's root: one [`LINE_BODY`].
    ///
    /// The step's `sub` is drawn on the Work page while the step runs. **One list rendered twice at
    /// two levels of detail, not two lists** — which is why this is a line box rather than a row
    /// height.
    PLAN_ROW_H:       Px = LINE_BODY;
    /// The most lines `Recipe::steps` can produce over every recipe this program can compose.
    ///
    /// `Start::FromIpsw` contributes fetch + build + install (3), `Loader::IPodLoader2` adds 1,
    /// Rockbox adds 2 and iPodLinux adds 2. A `Ratio` because it is a count, exactly as
    /// [`DRAWER_MAX_DEPTH`] is; emitted because the markup sizes the plan region from it.
    ///
    /// **It is a bound rather than an observation**, and the observation is the test's:
    /// `a_plan_is_never_more_than_eight_lines` enumerates every recipe rather than asserting this.
    PLAN_MAX_ROWS:    Ratio = 8.0;
    /// §11.3 item 3: *a 60 %-opacity material* under a `Fix` row.
    ///
    /// **It has to be a constant rather than a literal.** `no_opacity_literal_outside_the_cosmetic_
    /// set` sweeps every binding whose name ends `-opacity` against a closed list of five cosmetic
    /// press-and-hold states, and 0.6 is not one of them: it is a design constant like
    /// [`GHOST_OPACITY`], decided by the document, not a press state decided by the drawing. It
    /// reaches the markup as `Geometry.fix-opacity`, which is a name and not a number, so the sweep
    /// passes it.
    FIX_OPACITY:      Ratio = 0.6;
    /// The width §11.3's refusal paragraph wraps at. **Written as the expression**, so re-deciding
    /// the page margin moves it.
    ///
    /// §11.3 says *388 px of measure*, and 388 is `420 − 2 × 16` — a margin this drawer does not
    /// use. Every page in it insets by [`PAGE_MARGIN`] 24, which is what `compose::Step`'s own doc
    /// quotes. The document's number is left unresolved rather than absorbed into a new inset term
    /// invented to make the two agree.
    REFUSAL_MEASURE:  Px = DRAWER_W - 2.0 * PAGE_MARGIN;
    /// §11.3's *4–6 lines*, as the cap on the refusal `Expand`. Derived, so a re-measured
    /// [`LINE_BODY`] moves it.
    REFUSAL_MAX_H:    Px = 6.0 * LINE_BODY;

    // ── §11.4's Parts ──────────────────────────────────────────────────────────────────────────

    /// A Parts row: a Row, plus the `Provenance::line()` beneath it at [`LINE_LABEL`].
    ///
    /// The same arithmetic `Pressable.sub` produces, declared so the fit test reads a constant
    /// rather than re-deriving one.
    PART_ROW_H:       Px = ROW_H + LINE_LABEL;
    /// §11.4's group heading and its count, on the rows' own rhythm.
    GROUP_HEAD_H:     Px = ROW_H;
    /// §11.4's boot-screen preview: the framebuffer's own width in logical px, at 1:1.
    ///
    /// Tied to `emu::FB_W` by `the_preview_is_the_framebuffers_own_size` rather than by a comment,
    /// because a preview drawn at anything but 1:1 is a resampled framebuffer presented as a
    /// screenshot.
    PREVIEW_W:        Px = 320.0;
    /// The same for `emu::FB_H`.
    PREVIEW_H:        Px = 240.0;
    /// The black glass around §11.4's preview — §6.1's geometric tell at `k = 1`.
    ///
    /// **Written as the product, never as a typed 10.5**, so a re-measured [`BEZEL_RATIO`] moves
    /// it. It is [`bezel_phys`] at `k = 1` by construction, and
    /// `the_preview_glass_is_the_bezel_at_one_to_one` is what holds the two together.
    PREVIEW_GLASS:    Px = BEZEL_RATIO * HERO_PHYS_1X;

    // ── The window's own four constants ──
    //
    // §16.1: these are plain constants and they must never read `hero`. If either height were bound
    // to the body the loop would close and oscillate, and this is the sentence that stops somebody
    // tidying it. `the_window_constants_do_not_read_the_hero` is the mechanical form of it.

    /// Derived in one line rather than in two disagreeing ones — see
    /// `the_min_width_derivation_sums_to_the_declared_minimum`.
    MIN_WIDTH:        Px = 880.0;
    /// **A floor, not a fit.** A minimum tall enough to guarantee the 1:1 panel would have to vary
    /// with `k` and `sf`, and a window minimum is a constant. This is the height below which even
    /// §9.5's replacement pane cannot be laid out; everything above it is the too-short boolean's
    /// job.
    ///
    /// **And the pane it defers to is built**, which is worth saying here because this is the
    /// constant that makes the state reachable: `bench.slint`'s `ShortPane` replaces the well
    /// whenever `too-short` is true, and [`SHORT_MEASURE`] plus [`SHELF`] is the column it has to
    /// fit inside this floor. The paragraph that used to stand here recorded the opposite —
    /// *computed, pushed in, and read by no markup* — and with it the state between this floor and
    /// roughly 810 logical, where the 655.751 px device was laid out past the bottom edge and
    /// drawn there. `the_short_pane_fits_the_window_minimum` is the arithmetic and
    /// `main::the_short_pane_replaces_the_bench_below_the_threshold_and_not_above_it` is the
    /// drawing.
    MIN_HEIGHT:       Px = 400.0;
    PREF_WIDTH:       Px = 1180.0;
    /// The k = 1, sf = 1 case of body + [`CHROME_PREF`], rounded up. Not a round number.
    PREF_HEIGHT:      Px = 846.0;

    // ── The two small drawings (§6.6) ──
    //
    // The same drawing at a different `body-height`, and neither is a framebuffer, so neither has
    // a `k`.

    /// The drawer's Devices list.
    ROW_BODY:         Px = 40.0;
    /// A Parts row for an iPod resource.
    THUMB_BODY:       Px = 24.0;
}

// ── Rust-only. NOT emitted: not scalars Slint can hold, or not read by markup. ──

/// §16.10's sweep of display scale factors.
///
/// `#[cfg(test)]` rather than `#[allow(dead_code)]`: nothing outside a test sweeps scale factors,
/// and a constant kept alive by an allow is the shape §16.9 deletes.
#[cfg(test)]
pub const SF_SWEEP: [f64; 10] = [1.0, 1.25, 1.5, 1.75, 2.0, 2.25, 2.5, 2.75, 3.0, 3.5];

/// The largest whole-number framebuffer scale this program will choose.
///
/// A 4K portrait display could legitimately ask for 5 or 6; the clamp is the sweep's own bound and
/// it is stated here rather than hidden in an arithmetic accident.
pub const K_MAX: i32 = 8;

/// §9.6: drop below the threshold, restore 20 px above it.
///
/// The asymmetry is the whole point — a symmetric comparison flutters under a drag exactly at the
/// boundary, which is a window that flickers between two layouts while the mouse is down.
pub const HYSTERESIS: f64 = 20.0;

// ── §11.2's two page heights. Rust-only, and deliberately ───────────────────────────────────────
//
// Neither is a position or a size any element is given: they are the SUM of the elements a page
// puts inside itself, checked against the drawer it has to fit in. Emitting them would put a total
// in the same global as the terms it is made of, which is an invitation to write
// `height: Geometry.composer-root-h` on a page whose own layout would then disagree with its parts.
// The markup lays each page out of its terms; these are what the fit test reads.
//
// Both are written as their terms rather than as a number, so re-measuring any one term moves the
// total — which is the whole of why they are constants and not literals in a test body.
//
// **`#[cfg(test)]` rather than `#[allow(dead_code)]`**, and that is [`SF_SWEEP`]'s own precedent
// stated once more: nothing outside a fit test sums a page, and a constant kept alive by an allow
// is the shape §16.9 deletes. `build.rs` compiles this file too and wants neither.

/// §11.2's root page, with **no refusal open**: the header, three numbered rows, the
/// always-reserved verdict, the plan's heading and its eight lines, the two ledger lines, the
/// pinned `Create`, the page margins, and three gaps between the four bands.
///
/// ```text
/// DRAWER_HEADER_H 44 + 3×ROW_H 132 + VERDICT_H 54 + LINE_LABEL 16
///   + PLAN_MAX_ROWS×PLAN_ROW_H 160 + 2×LINE_LABEL 32 + PRIMARY_FOOTER_H 68
///   + 2×PAGE_MARGIN 48 + 3×FOOTER_PAD 36  =  590
/// ```
///
/// Against `722 − SHELF` = 634 — §11.2's own stated window minimum — that is 44 px of slack, which
/// is what `the_composer_root_fits_the_smallest_window_that_draws_the_device` exists to hold.
#[cfg(test)]
pub const COMPOSER_ROOT_H: f64 = DRAWER_HEADER_H
    + 3.0 * ROW_H
    + VERDICT_H
    + LINE_LABEL
    + PLAN_MAX_ROWS * PLAN_ROW_H
    + 2.0 * LINE_LABEL
    + PRIMARY_FOOTER_H
    + 2.0 * PAGE_MARGIN
    + 3.0 * FOOTER_PAD;

/// §11.2's level ① — *Which iPod*: the header, one `Pick`-shaped row per iPod/Model/Colour, and the
/// two identity `Field`s, each reserving its two-line slot, then the `TitleAuth` paragraph.
///
/// ```text
/// DRAWER_HEADER_H 44 + ROW_H 44 + 4×(ROW_H + FIELD_REASON) 312
///   + 5×LINE_BODY 100 + 2×PAGE_MARGIN 48  =  548
/// ```
///
/// **The four is not a typo and it is the point of §11.1.** Model, Colour, Serial and GUID all
/// reserve the same slot whether they are open or locked, so a retail dump and a synthesised ROM
/// draw the same controls at the same heights and the surface does not jump when you switch
/// between them. Collapsing the locked case to a line of text would make this 4 × 44 and would be
/// the jump.
#[cfg(test)]
pub const LEVEL_ONE_H: f64 =
    DRAWER_HEADER_H + ROW_H + 4.0 * (ROW_H + FIELD_REASON) + 5.0 * LINE_BODY + 2.0 * PAGE_MARGIN;

// ── Two type budgets, and neither is emitted ────────────────────────────────────────────────────
//
// The rule at the top of this section is *not scalars Slint can hold, or not read by markup*, and
// these are the second kind. Emitting them would be worse than useless: nothing in `.slint` can ask
// how long a string is, so `cradle-label-max-chars` would be a property no expression could use,
// and `body-advance` would be a bare multiplier sitting in the same global as the lengths — an
// invitation to write `width: Geometry.body-advance * something` in markup, which the literal sweep
// cannot catch because a name is not a number.
//
// They are budgets rather than measurements. Both say so, and both name the command that settles
// them.

/// §6.2's `body` size, 14 px. **A duplicate of `Metric.body-size`, bounded and asserted** — the
/// same arrangement [`PAGE_MARGIN`] has with `Metric.s5`, and for the same reason: `ui/tokens.slint`
/// owns §6.2's type scale, this file owns geometry, and a column width derived from a type size has
/// to name one. `the_rail_verb_column_holds_the_longest_verb` reads `body-size` out of
/// `ui/tokens.slint` as text, so the two cannot drift.
pub const BODY_SIZE: f64 = 14.0;

/// A conservative average glyph advance, as a fraction of [`BODY_SIZE`].
///
/// **Unmeasured, and it is in [`RAIL_VERB_W`]'s shape rather than in the design's**: no constant in
/// this program is allowed to be a number somebody liked, so this one carries what it is. It exists
/// so that a column width and a label budget can be checked with no renderer running — Slint 1.17
/// exposes no text-measurement API to Rust, and `i-slint-core`'s own `text_size` needs a live
/// window adapter.
///
/// 0.62 is deliberately **pessimistic** for mixed-case English prose in a system UI face, where the
/// true average is nearer 0.5: a budget that over-estimates how wide a string is refuses strings
/// that would have fitted, and a budget that under-estimates ships one that elides. Of the two, the
/// first is the failure that can be seen in a test.
///
/// **MEASURED 2026-08-21, macOS 27.0, scale 2: 0.479.** `synthesise` — ten characters — draws
/// 67.0 logical px at 14 px, through `MainWindow.verb-width`, which `IPOD_LAYOUT=1` prints on its
/// `verb` line. So the true average on this platform is nearer 0.48 than 0.5, and the pessimism
/// above is real pessimism rather than a hope.
///
/// **It stays 0.62 anyway.** One platform's system face is not every platform's, and the two things
/// derived from this fail in opposite directions: a column narrower than the text **elides**, and a
/// label budget wider than the row **elides**. A single number above the measured advance is
/// conservative for both. [`RAIL_VERB_W`] is now checked against the platform's own answer as well,
/// by `the_verb_column_holds_the_verb_this_platform_draws`; this stays the floor under it.
pub const BODY_ADVANCE: f64 = 0.62;

/// **The narrowest measure §9.4's reason is ever drawn at**, and therefore the budget every reason
/// in this program has to clear.
///
/// A reason is one line with `overflow: elide` in a 34 px slot (`primitives.slint`'s `ReasonSlot`).
/// It cannot wrap — §9.6's vertical budget is built on fixed row heights, and §17.Q1 has already
/// decided once that a paragraph does not get permanent chrome — so the only way a reason is
/// legible is by being short enough for the narrowest column that draws it.
///
/// **Four columns draw one, and this is the smallest**: §9.3's next-step pair at [`RAIL_NEXT_W`]
/// less the control's own `Metric.s3` of padding on each side, `170 − 24 = 146`. The other three are
/// wider and clear it with room — §11.4's group verbs at `(372 − 12) / 2 = 180`, a Parts or Devices
/// act at `420 − 4 × PAGE_MARGIN = 324`, a Settings row or a Parts fact line at
/// [`REFUSAL_MEASURE`] 372.
///
/// **`Next::reason` is drawn in three of the four, so it is written to this one**, and that much of
/// the original rule stands: a sentence written to the column it happens to be in today elides the
/// first time it is reused one column over.
///
/// **What did not stand is applying it to sentences that are drawn in exactly one slot.** §11.3's
/// `consequence` shares the slot and is not a refusal — it is what the second press will do, read
/// once, at one control, on one page — and no arrangement of English puts *what a destructive act
/// costs* in 146 px. Held to this number, `parts::remove_consequence` could not name the seed
/// §11.4 requires of it. So the budget is now **the slot the sentence is actually drawn in**
/// ([`ACT_MEASURE`], [`PARTS_VERB_W`], [`REFUSAL_MEASURE`], or this), and the sweep carries the
/// slot with the sentence rather than measuring everything against the smallest.
///
/// **It is not a character count.** `the_group_verb_column_holds_every_verb_this_page_draws` found
/// `Add a dump…` wider than `Synthesise…` at equal length, so this is checked with the renderer —
/// `MainWindow.reason-width`, at `Metric.label-size` and `Metric.weight-label`, which is the face
/// `ReasonSlot` draws in. `every_reason_this_window_draws_fits_the_slot_it_is_drawn_in` is the
/// gate; [`BODY_ADVANCE`] is not in it anywhere, because a budget derived from an average advance
/// is the guess that measurement replaces.
#[cfg(test)]
pub const REASON_MEASURE: f64 = RAIL_NEXT_W - 2.0 * 12.0;

/// **§9.4's widest slot, and the one two primitives disagreed about by 48 px without saying so.**
///
/// A `Field`'s row carries no padding of its own, so its `ReasonSlot` gets the whole page body:
/// [`REFUSAL_MEASURE`] 372. A `Pressable` in the same column indents by its own `pad`, which every
/// use site in this markup sets to [`PAGE_MARGIN`] — so it gets [`ACT_MEASURE`] 324 instead. On
/// `ui/composer.slint` the two are four rows apart and
/// `Read from the dump; a device's identity is the ROM's, not ours.` drew whole under `Serial` and
/// elided to *…not …* under `Model`. One string, one page, two answers, and the difference was
/// invisible because `Field` took `ReasonSlot`'s `0px` default by omission rather than stating it.
///
/// The difference is kept — a reason lines up under the label it is about, and the two labels are
/// not at the same x — and is now **stated at both use sites and measured at both**:
/// `MainWindow.field-reason-w` and `MainWindow.act-reason-w` build one of each and report what its
/// slot handed its `Text`. `the_two_reason_slots_differ_by_exactly_the_pad_that_indents_one_of_them`
/// is the gate, and it reads the renderer rather than this arithmetic.
#[cfg(test)]
pub const PAGE_REASON_MEASURE: f64 = REFUSAL_MEASURE;

/// **The measure a §9.4 reason gets under an act** — a `Pressable` padded by [`PAGE_MARGIN`] inside
/// a page body that is already inset by one.
///
/// Six controls in three files: Parts' `Remove` and its `Detail` acts (`parts.slint:65`, `:242`),
/// Devices' `Edit…` / `Remove` / `Start` and the `New device` footer (`devices.slint:58`, `:282`,
/// `:336`), and the Composer's picker rows (`composer.slint:71`). It is where every `consequence`
/// in this program that is not a Rail next-step lands, which is why it is the number
/// `removal_consequence` and `remove_consequence` are written to.
///
/// `420 − 4 × PAGE_MARGIN`, written as the expression so a re-decided margin moves it — the same
/// arrangement [`REFUSAL_MEASURE`] already has.
#[cfg(test)]
pub const ACT_MEASURE: f64 = REFUSAL_MEASURE - 2.0 * PAGE_MARGIN;

/// How many characters §7.3's cradle label may carry before it elides.
///
/// **Written as the expression rather than as 48**, so a re-measured [`BODY_ADVANCE`] or a
/// re-measured body moves every sentence that has to fit rather than leaving a stale number here.
/// The label is `width: frame.width` (`ui/bench.slint:481`), and the frame is the body plus one
/// [`CRADLE_BAND`] on each side:
///
/// ```text
/// (BODY_ASPECT × HERO_PHYS_1X + 2 × CRADLE_BAND) / (BODY_ADVANCE × BODY_SIZE)
///  = (388.0 + 32.0) / 8.68
///  = 48.4  →  48
/// ```
///
/// **It is a floor and not a ceiling.** `hero` is the *logical* body height, which is
/// `HERO_PHYS_1X` only at `k = 1, sf = 1`; every larger window draws a wider label. So a sentence
/// that fits this fits everywhere, and one that does not elides on the smallest window that draws
/// the device at all — which is the case worth refusing.
///
/// Truncating rather than rounding is the same conservatism: 48.4 characters is 48 characters.
#[allow(dead_code)]  // retired when: a first-run cradle label is composed at run time rather than typed — the shipped labels are checked against this budget by `every_typed_cradle_label_fits_its_own_row`, and the shipped binary consults it nowhere yet
pub const CRADLE_LABEL_MAX_CHARS: usize =
    ((BODY_ASPECT * HERO_PHYS_1X + 2.0 * CRADLE_BAND) / (BODY_ADVANCE * BODY_SIZE)) as usize;

/// `SCREEN_W` → `"screen-w"`. The only mangling, and it is total.
pub fn slint_name(rust_name: &str) -> String {
    rust_name.to_ascii_lowercase().replace('_', "-")
}

/// Render one `f64` as a Slint numeric literal.
///
/// `{:?}` is the shortest round-tripping form, which is what we want — but for a value below about
/// 1e-4 it emits `1e-5`, and **Slint's lexer reads the `e` as a unit**. Every constant above formats
/// plainly; the assert is here so that a future one that does not fails the build script, with its
/// own value in the message, rather than failing the markup.
///
/// Verified rather than assumed: with this assert removed and a `TINY: Ratio = 1.0e-5` added, the
/// build stops at
///
/// ```text
/// error: Invalid unit 'e'. Valid units are: %, phx, px, cm, mm, in, pt, rem, s, ms, deg, grad,
///        turn, rad
///   --> …/out/geometry.slint:23:32
///    |
/// 23 |     out property <float> tiny: 1e-5;
/// ```
///
/// — pointing at a generated file nobody edited, which is the diagnosis this assert replaces.
//
// Compiled by `build.rs` as well as by the crate, and only the build script calls it — hence the
// allow. It comes off if the window ever needs to print a Slint literal at run time, which it does
// not today.
#[allow(dead_code)]  // retired when: the window needs to print a Slint literal at run time, which it does not today
pub fn slint_number(v: f64) -> String {
    let s = format!("{v:?}");
    assert!(
        s.bytes().all(|b| b.is_ascii_digit() || b == b'.' || b == b'-'),
        "{s} is not a plain decimal; Slint's lexer reads the exponent as a unit"
    );
    s
}

/// The whole generated `.slint` file, as text.
///
/// Called by `build.rs` **and** by `the_generated_file_is_byte_identical_to_the_source_of_truth`,
/// so a non-deterministic byte here — a timestamp, a hash-map order, an absolute path — is caught
/// by a test rather than by four consecutive rebuilds that each recompile.
#[allow(dead_code)]  // retired when: never — `build.rs` and `the_generated_file_is_byte_identical_to_the_source_of_truth` are both real callers, and the allow exists because the crate compile sees neither
pub fn slint_source() -> String {
    let mut out = String::new();
    out.push_str("// generated by build.rs from src/geometry.rs — do not edit\n");
    out.push_str("export global Geometry {\n");
    for (name, unit, value) in ALL {
        let (ty, suffix) = match unit {
            Unit::Ratio => ("float", ""),
            Unit::Px => ("length", "px"),
        };
        out.push_str(&format!(
            "    out property <{ty}> {}: {}{suffix};\n",
            slint_name(name),
            slint_number(*value)
        ));
    }
    out.push_str("}\n");
    out
}

// ── The one-way arrow of §6.6 ───────────────────────────────────────────────────────────────────
//
// Nothing below takes a window. `hero` is pushed into the markup from Rust and never read back out
// of it, and the only way to keep that true is for the arithmetic to have no way of asking.

/// The symmetric inset of the screen from the left edge of the body.
///
/// An **output** since §6.6 took the screen's size off the drawing: `(BODY_ASPECT − SCREEN_W) / 2`.
/// It differs from [`SCREEN_TOP`] by 0.00065 of body height — 0.43 px at hero, 0.07 mm on a real
/// device — and that agreement is how the parse was confirmed to have found the display rather than
/// some other rectangle in a drawing full of rectangles.
pub fn left_inset() -> f64 {
    (BODY_ASPECT - SCREEN_W) / 2.0
}

/// The black surround, in physical pixels. 10.49, four sides, every `k`, every scale factor.
pub fn bezel_phys() -> f64 {
    BEZEL_RATIO * HERO_PHYS_1X
}

/// The body height in PHYSICAL pixels at framebuffer scale `k`.
pub fn hero_phys(k: i32) -> f64 {
    f64::from(k) * HERO_PHYS_1X
}

/// The body height in LOGICAL pixels — the length pushed into the markup.
pub fn hero_logical(k: i32, sf: f64) -> f64 {
    hero_phys(k) / sf
}

/// The whole-number framebuffer scale a given amount of logical height can hold.
///
/// Never below 1: a client shorter than [`CHROME_MIN`] floors negative and comes back as `k = 1`
/// with the too-short boolean set, which is §9.5 and is correct rather than a special case.
pub fn decide_k(avail_logical: f64, sf: f64) -> i32 {
    let raw = ((avail_logical - CHROME_MIN) * sf) / HERO_PHYS_1X;
    let k = raw.floor().max(1.0);
    (k as i32).min(K_MAX)
}

/// Walk a logical length up until it survives the round-trip through `f32` and back into physical
/// pixels — that is, until `f32(w) × sf` is **not below** the framebuffer it has to hold.
///
/// `Coord = f32` in `i-slint-core`, so the round-trip that matters is the f32 one, and **the walk
/// has to be in f32 steps**. The first version of this stepped `f64::next_up`, which is a relative
/// 2⁻⁵² — about 2⁻²⁹ of one step of the f32 grid it was trying to cross. Sixty-four of them cannot
/// move the f32 value at all, so the loop always ran out and handed back exactly what it was given.
/// It looked like it worked because in 120 of the 160 swept `sf × k` cases the plain division is
/// already exact; in the other 40 — every `sf` of 1.5, 1.75, 2.25, 3.0, 3.5 and some of 2.75 — the
/// panel came back a fraction of a pixel **short** of `k × 320`, which is a framebuffer column
/// thrown away wherever the renderer truncates rather than rounds. Measured, not assumed: the
/// sweep in `the_panel_is_an_exact_integer_number_of_device_pixels` reports 40 short before the
/// step is fixed and 0 after, and the worst overshoot afterwards is 0.00015 px — inside the black
/// glass, where nobody can see it.
pub fn next_up_until(target_phys: f64, sf: f64) -> f64 {
    let mut w = (target_phys / sf) as f32;
    for _ in 0..64 {
        if f64::from(w) * sf >= target_phys {
            return f64::from(w);
        }
        w = w.next_up();
    }
    f64::from(w)
}

/// The panel, in logical pixels, at framebuffer scale `k`.
pub fn panel_logical(k: i32, sf: f64) -> (f64, f64) {
    let k = f64::from(k);
    (
        next_up_until(k * 320.0, sf),
        next_up_until(k * 240.0, sf),
    )
}

/// The black glass, in physical pixels — **computed from the panel**, never from a ratio.
///
/// The previous revision computed `k` from a glass whose own ratio was 1.3066, so the two ratios
/// §6.6 exists to correct governed nothing except where the glass sat. Making the glass an output
/// is what stops a re-measured bezel silently flipping which axis bounds `k`.
pub fn glass_phys(k: i32) -> (f64, f64) {
    let k = f64::from(k);
    let b = 2.0 * bezel_phys();
    (k * 320.0 + b, k * 240.0 + b)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The text `build.rs` wrote into `OUT_DIR`, as the crate's own compile saw it.
    const GENERATED: &str = include_str!(concat!(env!("OUT_DIR"), "/geometry.slint"));

    /// **Every `.slint` file this phase declares.** The list is here so the sweeps below can be
    /// checked *both* ways: a file on disk that is not in this list is unswept, and a name in this
    /// list that is not on disk is a sweep pointing at nothing.
    ///
    /// The two-name array this replaced was written when there were two markup files, and five more
    /// have landed since. A sweep that names its own inputs stops sweeping the moment somebody adds
    /// a file — silently, and looking exactly like a sweep that found nothing.
    const DECLARED_MARKUP: &[&str] = &[
        "bench.slint",
        // §11.2's three depth levels and their root. Declared the day the file landed, which is
        // what this list is for: every sweep below reads `markup()`, so a file nobody declared is
        // one being swept without anybody having decided it should be.
        "composer.slint",
        // §7.2's Devices page — device selection lives here, not on the bench.
        "devices.slint",
        "drawer.slint",
        "ipod.slint",
        // §11.4's six groups.
        "parts.slint",
        // §12.8's seven groups of Gauges, its fixed header and its two pinned actions.
        "readout.slint",
        // §11.6's one page and three rows.
        "settings.slint",
        // A second top-level `Window`, for `slint-viewer` only. **`build.rs` must keep exactly one
        // `compile*` call** — a second one clobbers `cargo:rustc-env=SLINT_INCLUDE_GENERATED` and
        // `MainWindow` stops existing, with the failure reading `cannot find type MainWindow in
        // this scope` — so this file is never a compile root and reaches the binary only if
        // something imports it.
        "preview.slint",
        "primitives.slint",
        "rail.slint",
        "tokens.slint",
        "window.slint",
        "work.slint",
    ];

    fn ui_dir() -> std::path::PathBuf {
        std::path::PathBuf::from(concat!(env!("CARGO_MANIFEST_DIR"), "/ui"))
    }

    /// Every `.slint` file **on disk**, name and text, sorted. Read at run time rather than
    /// `include_str!`'d, because the point is to see what is there rather than what was there when
    /// this was compiled.
    fn markup() -> Vec<(String, String)> {
        let mut out: Vec<(String, String)> = std::fs::read_dir(ui_dir())
            .expect("the ui directory")
            .flatten()
            .map(|e| e.path())
            .filter(|p| p.extension().is_some_and(|x| x == "slint"))
            .map(|p| {
                let name = p.file_name().unwrap().to_string_lossy().into_owned();
                let text = std::fs::read_to_string(&p)
                    .unwrap_or_else(|e| panic!("could not read {}: {e}", p.display()));
                (name, text)
            })
            .collect();
        out.sort();
        out
    }

    /// One file's text, by name. Panics rather than skipping: a sweep that quietly finds no file is
    /// the instrument that reports an absence it could not have observed.
    fn read(name: &str) -> String {
        markup()
            .into_iter()
            .find(|(n, _)| n == name)
            .unwrap_or_else(|| panic!("ui/{name} is not on disk"))
            .1
    }

    /// §9.6's `min-width` has ONE derivation, and this is it.
    ///
    /// The document's own parenthetical — *"12 handle + 24 + 389.3 + 24"* — summed to 449.3 beside a
    /// declared 880, which is two sources of truth for a load-bearing constant in the section whose
    /// rule is that constants live in one place. So the derivation becomes the check.
    #[test]
    fn the_min_width_derivation_sums_to_the_declared_minimum() {
        let needed = DRAWER_W
            + BODY_ASPECT * HERO_PHYS_1X
            + 2.0 * CRADLE_OVERHANG
            + 2.0 * FOCUS_GAP
            + 2.0 * WELL_AIR;
        assert!(
            (needed - MIN_WIDTH).abs() < 0.05,
            "the well needs {needed:.1} px and the window declares {MIN_WIDTH:.1}"
        );
    }

    /// §9.6: `min-height` is a **floor**, not a fit.
    ///
    /// A window whose declared minimum claimed to hold the device would be in silent conflict with
    /// the fidelity rule, and the layout wins that argument — which is what the test this replaces
    /// (`the_window_minimum_holds_the_device`) asserted as a *requirement*.
    //
    // The relationship between two declared constants IS the thing under test, so clippy's
    // "this assertion has a constant value" is describing the point rather than a defect. Not moved
    // into a `const` block on purpose: a failure here should name both numbers at test time, the
    // way every other check in this module does, rather than stop the build with a const-eval
    // panic.
    #[allow(clippy::assertions_on_constants)]
    #[test]
    fn the_minimum_height_is_a_floor_not_a_fit() {
        assert!(
            MIN_HEIGHT < HERO_PHYS_1X + CHROME_MIN,
            "a declared minimum of {MIN_HEIGHT:.0} that held a {:.0} px device would make the \
             too-short state unreachable, and §9.5 is a designed state",
            HERO_PHYS_1X + CHROME_MIN
        );
    }

    /// **The other half of that floor, and §9.5's pane is what stands on it.**
    ///
    /// The test this replaces — `the_too_short_state_is_an_input_with_nothing_reading_it` — asserted
    /// that `too-short` appeared in `window.slint` exactly once, as its own declaration, and
    /// nowhere else in the markup. It was the right test while the gap was open and the wrong one
    /// the moment it closed, which is what it said about itself.
    ///
    /// What replaces it here is the arithmetic that makes the pane possible at all: at the window
    /// minimum, with the shelf taking [`SHELF`] off the bottom, there is room for §9.5's primary
    /// Row **and** its two sentences. That is the claim [`MIN_HEIGHT`] is making by being a floor —
    /// *the height below which even §9.5's replacement pane cannot be laid out* — and nothing was
    /// checking it. The drawing itself is asserted one level up, by
    /// `main::the_short_pane_replaces_the_bench_below_the_threshold_and_not_above_it`, which reads
    /// the accessible tree rather than this file.
    ///
    /// The terms are the pane's own column: [`WELL_AIR`] above and below, `Metric.s4` between each
    /// pair — read out of `ui/tokens.slint` as text, the arrangement [`PAGE_MARGIN`] already has
    /// with `s5` — and **one** [`LINE_BODY`] per sentence, which is a floor rather than a
    /// measurement. Both sentences wrap, so what this asserts is that the Row and a first line of
    /// each of them fit; `_out/gui/bench-too-short.png` is where the real renderings are read, and
    /// at [`SHORT_MEASURE`] they are one line and three, leaving 116 px of the 312 unspent. A
    /// budget that tried to predict a line count would be arithmetic about a text renderer this
    /// file cannot ask.
    #[test]
    fn the_short_pane_fits_the_window_minimum() {
        let s4 = markup_space("s4");
        let well = MIN_HEIGHT - SHELF;
        let column = 2.0 * WELL_AIR + LINE_BODY + s4 + LINE_BODY + s4 + ROW_H;
        assert!(
            column <= well,
            "§9.5's pane needs {column:.0} px and the window minimum leaves it {well:.0}; \
             MIN_HEIGHT {MIN_HEIGHT:.0} is supposed to be the height below which the pane cannot \
             be laid out, so either it is too low or the pane's column has grown"
        );
    }

    /// §9.5's measure never overflows the well, at any size this window allows.
    ///
    /// The binding case is the declared minimum width **with the drawer open**, which §9.6 spends a
    /// paragraph on: the drawer never widens the window, so the well gives up `DRAWER_W` and what
    /// is left is all the pane will ever have. [`SHORT_MEASURE`] is that number less §7.1's air, so
    /// this is the derivation checked rather than restated — the same shape as
    /// `the_min_width_derivation_sums_to_the_declared_minimum` one screen up.
    #[test]
    fn the_short_pane_fits_the_narrowest_well_this_window_has() {
        let narrowest = MIN_WIDTH - DRAWER_W;
        assert_eq!(
            SHORT_MEASURE + 2.0 * WELL_AIR,
            narrowest,
            "the pane is set at {SHORT_MEASURE} across with {WELL_AIR} of air a side, and the \
             narrowest well this window has is {narrowest}"
        );
    }

    /// [`CHROME_MIN`] and [`CHROME_PREF`] are not typed-in totals.
    ///
    /// This is §16.10's `the_column_fits_the_declared_minimum`, re-expressed. Its stated assertion
    /// — `sum <= min_height` — is arithmetically impossible under §9.6's own numbers (809.751 ≤ 400
    /// holds at no `k` and no `sf`), so implementing it verbatim would produce a test that can only
    /// fail and would then be weakened until it passed. What §9.6 actually establishes is that the
    /// column's terms sum to the declared chrome, **including the cradle band above the body as
    /// well as below it**, and that is asserted here exactly.
    #[test]
    fn the_column_terms_sum_to_the_declared_chrome() {
        let min = MARGIN_TOP_MIN
            + CRADLE_BAND
            + CRADLE_BAND
            + GAP_1_MIN
            + CRADLE_LABEL
            + GAP_2_MIN
            + SHELF;
        assert_eq!(
            min, CHROME_MIN,
            "the minimum column sums to {min} and CHROME_MIN declares {CHROME_MIN}"
        );

        let pref =
            MARGIN_TOP + CRADLE_BAND + CRADLE_BAND + GAP_1 + CRADLE_LABEL + GAP_2 + SHELF;
        assert_eq!(
            pref, CHROME_PREF,
            "the preferred column sums to {pref} and CHROME_PREF declares {CHROME_PREF}"
        );
    }

    /// `preferred-height` is the k = 1, sf = 1 case of body + chrome, not a round number.
    #[test]
    fn the_preferred_height_holds_the_device_at_k_one() {
        let want = (HERO_PHYS_1X + CHROME_PREF).ceil();
        assert_eq!(
            want, PREF_HEIGHT,
            "the body plus the preferred column is {want} and PREF_HEIGHT declares {PREF_HEIGHT}"
        );
    }

    /// §6.6's tell that the well is 4:3: the two derivations of the hero agree.
    #[test]
    fn the_two_hero_derivations_agree() {
        let from_h = 240.0 / SCREEN_H;
        assert!(
            (HERO_PHYS_1X - from_h).abs() < 0.01,
            "320/SCREEN_W is {HERO_PHYS_1X:.4} and 240/SCREEN_H is {from_h:.4}; they are supposed \
             to be the same number to four figures"
        );
        let ratio = SCREEN_W / SCREEN_H;
        assert!(
            (ratio - 4.0 / 3.0).abs() < 1e-5,
            "the well is {ratio:.5}, not 4:3 — a 320×240 buffer would be stretched in one axis only"
        );
    }

    /// §16.10 and §20 item 10. **The panel is a whole number of device pixels at every scale
    /// factor and every `k`, and never one short of it.**
    ///
    /// The framebuffer is 320 × 240 and §2.8 allows whole-number scales only, so the drawn panel
    /// has to land on exactly `k × 320` by `k × 240` **physical** pixels. Two halves, and the
    /// second is the one that was broken:
    ///
    /// - it must **round** to that, or a row or column of the frame is duplicated or dropped;
    /// - it must not be **below** it, because a renderer that truncates rather than rounds turns
    ///   `319.99999` into 319 — the 560 px bug at a hundredth of the scale.
    ///
    /// It swept `sf ∈ SF_SWEEP × k ∈ 1..=K_MAX` — 160 cases — and found 40 short, which is what
    /// made [`next_up_until`] a real function rather than a decorative one: it was stepping f64
    /// ULPs across an f32 grid and could never move the value it was handed. The existing
    /// `the_panel_is_an_exact_whole_number_of_pixels` in `main.rs` checks `k = 1, sf = 1`, which
    /// §16.10 says is precisely the case that is not interesting.
    #[test]
    fn the_panel_is_an_exact_integer_number_of_device_pixels() {
        let mut short = Vec::new();
        for sf in SF_SWEEP {
            for k in 1..=K_MAX {
                let (w, h) = panel_logical(k, sf);
                // Through `f32` and back, because that is what the markup holds and what the
                // renderer multiplies: `Coord = f32` in `i-slint-core`.
                for (logical, base, axis) in [(w, 320.0, "across"), (h, 240.0, "down")] {
                    let want = f64::from(k) * base;
                    let phys = f64::from(logical as f32) * sf;
                    if phys < want {
                        short.push(format!(
                            "sf {sf} k {k} {axis}: {phys:.6} physical for a {want} px \
                             framebuffer, {:.6} short",
                            want - phys
                        ));
                    }
                    assert_eq!(
                        phys.round() as i64,
                        want as i64,
                        "sf {sf} k {k} {axis}: {logical:.6} logical draws {phys:.6} physical, \
                         and the framebuffer is {want}"
                    );
                }
                // The same multiple on both axes, or it is a stretch rather than a scale — which
                // is what the pre-§6.6 `0.4866 / 0.3672` pair actually did.
                let across = f64::from(w as f32) * sf / (f64::from(k) * 320.0);
                let down = f64::from(h as f32) * sf / (f64::from(k) * 240.0);
                assert!(
                    (across - down).abs() < 1e-5,
                    "sf {sf} k {k}: {across:.7} across and {down:.7} down is a stretch"
                );
            }
        }
        assert!(
            short.is_empty(),
            "{} of {} swept cases draw the panel short of its own framebuffer:\n  {}",
            short.len(),
            SF_SWEEP.len() * K_MAX as usize * 2,
            short.join("\n  ")
        );
    }

    /// The ratio arm of the same obligation, and §16.10 asks for it by name: **put the old pair
    /// back and watch it go red.**
    ///
    /// A sweep that can only fail on the f32 tail would pass forever if somebody re-measured the
    /// screen wrongly, because `panel_logical` does not read the ratios at all. This is the arm
    /// that does, and it is the shape `the_old_ratios_would_fail_this_test` uses: hand the checker
    /// the values that shipped and require it to reject them.
    #[test]
    fn the_old_ratios_would_draw_the_panel_off_its_own_framebuffer() {
        // What `ui/ipod.slint` draws: `Geometry.screen-w * body-height`.
        let drawn = |hero: f64, ratio: f64| hero * ratio;
        let (sw, sh) = (0.4866, 0.3672);
        let w = drawn(HERO_PHYS_1X, sw);
        let h = drawn(HERO_PHYS_1X, sh);
        assert!(
            (w - 320.0).abs() > 0.1 || (h - 240.0).abs() > 0.1,
            "the pre-§6.6 pair {sw} / {sh} drew {w:.4} × {h:.4} and this test did not notice"
        );
        assert!(
            ((w / 320.0) - (h / 240.0)).abs() > 1e-4,
            "the pre-§6.6 pair is supposed to be a stretch: {:.6} across, {:.6} down",
            w / 320.0,
            h / 240.0
        );
        // And the pair in force is not.
        let w = drawn(HERO_PHYS_1X, SCREEN_W);
        let h = drawn(HERO_PHYS_1X, SCREEN_H);
        assert!(
            (w - 320.0).abs() < 0.01 && (h - 240.0).abs() < 0.01,
            "the ratios in force draw {w:.4} × {h:.4} for a 320 × 240 framebuffer"
        );
    }

    /// §6.6's glass, and the two functions that would otherwise be constants nobody checks.
    ///
    /// This is §16.10's `the_glass_is_the_panel_plus_ten_and_a_half_physical_pixels`, at the level
    /// the model can assert it: the surround is the same on all four sides at every `k`, and the
    /// glass is the panel plus it rather than a ratio of the body.
    #[test]
    fn the_glass_is_the_panel_plus_ten_and_a_half_physical_pixels() {
        assert!(
            (bezel_phys() - 10.49).abs() < 0.01,
            "the bezel is {:.2} physical px; §6.1 declares 10.49 as a checkable invariant",
            bezel_phys()
        );
        for k in 1..=K_MAX {
            let (gw, gh) = glass_phys(k);
            let across = gw - f64::from(k) * 320.0;
            let down = gh - f64::from(k) * 240.0;
            assert!(
                (across - down).abs() < 1e-9,
                "at k={k} the glass leaves {across:.4} across and {down:.4} down; the surround is \
                 supposed to be the same on all four sides"
            );
            assert!(
                (across / 2.0 - bezel_phys()).abs() < 1e-9,
                "at k={k} the surround is {:.4} per side, not {:.4}",
                across / 2.0,
                bezel_phys()
            );
        }
        let (gw, gh) = glass_phys(1);
        assert!(
            (gw - 341.0).abs() < 0.1 && (gh - 261.0).abs() < 0.1,
            "the glass at k=1 is {gw:.1} × {gh:.1}; §6.6 says 341.0 × 261.0"
        );
    }

    /// Nothing in [`ALL`] can be defined and then silently not emitted.
    #[test]
    fn every_geometry_constant_reaches_the_markup() {
        for (name, unit, value) in ALL {
            let suffix = match unit {
                Unit::Ratio => "",
                Unit::Px => "px",
            };
            let want = format!(
                "    out property <{}> {}: {}{suffix};\n",
                match unit {
                    Unit::Ratio => "float",
                    Unit::Px => "length",
                },
                slint_name(name),
                slint_number(*value)
            );
            assert!(
                GENERATED.contains(&want),
                "{name} is declared and never emitted; the generated file has no line\n{want}"
            );
        }
    }

    /// The first pair of names that mangle to the same Slint property, if there is one.
    fn first_collision(names: &[&str]) -> Option<(String, String, String)> {
        let mut seen: Vec<(String, &str)> = Vec::new();
        for name in names {
            let slint = slint_name(name);
            if let Some((_, other)) = seen.iter().find(|(s, _)| *s == slint) {
                return Some((name.to_string(), other.to_string(), slint));
            }
            seen.push((slint, name));
        }
        None
    }

    /// The Rust → Slint mangling is injective, so a rename cannot make two constants collide into
    /// one Slint property with the later one silently winning.
    ///
    /// **Honest limitation, and it is why the control below is half the test.** A real collision in
    /// [`ALL`] cannot make this assertion fire, because the generated file would then declare the
    /// same property twice and `build.rs` fails first — the crate never compiles, so no test runs.
    /// What this buys over Slint's own duplicate-property error is a message that names the two
    /// **Rust** constants, which the slint compiler cannot know about. The control is what proves
    /// the detector works at all.
    ///
    /// (`SCREEN__W` is *not* an example of a collision: two underscores mangle to two hyphens.
    /// Names differing only in case are, which is why the control uses one.)
    #[test]
    fn no_two_constants_share_a_slint_name() {
        let names: Vec<&str> = ALL.iter().map(|(n, _, _)| *n).collect();
        if let Some((a, b, slint)) = first_collision(&names) {
            panic!("{a} and {b} both mangle to `{slint}`");
        }

        // The control (AGENTS.md §6): before believing that nothing collided, make it collide.
        let (a, b, slint) = first_collision(&["SCREEN_W", "BODY_ASPECT", "Screen_w"])
            .expect("the collision detector cannot see a collision it is handed");
        assert_eq!((a.as_str(), b.as_str(), slint.as_str()), ("Screen_w", "SCREEN_W", "screen-w"));
    }

    /// Every emitted value is a plain decimal.
    ///
    /// Slint's lexer reads the `e` of `1e-5` as a unit. Verified, not assumed — a constant of
    /// `1.0e-5` makes `build.rs` stop with
    /// `error: Invalid unit 'e'. Valid units are: %, phx, px, cm, mm, in, pt, rem, s, ms, deg,
    /// grad, turn, rad`, pointing at the generated file.
    ///
    /// **Like `no_two_constants_share_a_slint_name`, the first half cannot be made red on its own**:
    /// an offending constant trips [`slint_number`]'s assert inside the build script, and if that
    /// were removed the slint compiler trips on the emitted file — either way the crate never
    /// compiles and no test runs. So the second half is the control: it proves the guard is armed
    /// by handing it the value.
    #[test]
    fn the_generated_slint_carries_no_scientific_notation() {
        for line in slint_source().lines() {
            let Some((_, rest)) = line.split_once(": ") else {
                continue;
            };
            let token = rest.trim_end_matches(';');
            let body = token.strip_suffix("px").unwrap_or(token);
            assert!(
                !body.is_empty()
                    && body
                        .bytes()
                        .all(|b| b.is_ascii_digit() || b == b'.' || b == b'-'),
                "`{token}` is not a plain decimal; Slint reads the exponent as a unit"
            );
        }

        // The control (AGENTS.md §6). `1.0e-5` formats as `1e-5`, which is what Slint chokes on.
        assert_eq!(format!("{:?}", 1.0e-5_f64), "1e-5");
        let armed = std::panic::catch_unwind(|| slint_number(1.0e-5)).is_err();
        assert!(
            armed,
            "slint_number let `1e-5` through; the build script would emit it and Slint would \
             report `Invalid unit 'e'` from a generated file nobody edited"
        );
    }

    /// The generated file and the source of truth are the same bytes.
    ///
    /// If [`slint_source`] ever became non-deterministic, the write-if-changed guard in `build.rs`
    /// would rewrite `geometry.slint` on every run, `slint-build`'s own `rerun-if-changed` would
    /// see it newer than the fingerprint, and the crate would recompile on every `cargo build`
    /// forever — which reads as Slint being slow rather than as a bug.
    #[test]
    fn the_generated_file_is_byte_identical_to_the_source_of_truth() {
        assert_eq!(
            GENERATED,
            slint_source(),
            "the file in OUT_DIR is not what slint_source() produces"
        );
    }

    /// `ui/geometry.slint` must not exist on disk.
    ///
    /// Under the `@geometry` library arrangement such a file would be ignored — an import beginning
    /// `@` is resolved **only** through the library paths (`i-slint-compiler/typeloader.rs:1259`).
    /// This guards against a later maintainer switching to `with_include_paths`, whose first
    /// candidate directory is the importing file's own, at which point a stale `ui/geometry.slint`
    /// would silently win over the generated one.
    #[test]
    fn the_markup_imports_the_generated_global_and_nothing_shadows_it() {
        let shadow = ui_dir().join("geometry.slint");
        assert!(
            !shadow.exists(),
            "{} exists; the generated global must have no file of that name to shadow it",
            shadow.display()
        );
        // **Every file on disk**, not the two that existed when this was written. A file that names
        // `Geometry.` without importing it is a compile error; the direction this catches is the
        // other one — a file that imports it and then hand-writes the number anyway, which the
        // literal sweep sees only if this list is complete.
        let mut named = 0;
        for (name, text) in markup() {
            let uses = text.contains("Geometry.");
            let imports = text.contains("from \"@geometry\"");
            if uses {
                named += 1;
                assert!(
                    imports,
                    "ui/{name} reads `Geometry.` and does not import the generated global"
                );
            } else {
                assert!(
                    !imports,
                    "ui/{name} imports the Geometry global and never reads it"
                );
            }
        }
        assert!(
            named >= 2,
            "only {named} markup files read the generated global; the drawn device and the window \
             both do"
        );
    }

    /// §16.1's one-way arrow, mechanically.
    ///
    /// The window's own four size constants must not read `hero`. `preferred-height: root.hero +
    /// Geometry.chrome-pref` is arithmetically the truest thing anybody could write there and is
    /// exactly the trap — it closes the loop, and Slint reports the inherited case as a deprecation
    /// *warning* saying it may panic at run time, which is the weaker signal this test upgrades.
    #[test]
    fn the_window_constants_do_not_read_the_hero() {
        // **Every** size constant in the file, not only the window's four: the pane that holds the
        // device is pinned to `min-height: 0px; preferred-height: 0px` for the same reason (§16.1,
        // "the container must declare no intrinsic height"), and a `hero` in either place closes
        // the same loop one level down.
        let window = read("window.slint");
        let mut seen = 0;
        for line in window.lines() {
            let t = line.trim();
            for prop in ["min-width:", "min-height:", "preferred-width:", "preferred-height:"] {
                if t.starts_with(prop) {
                    seen += 1;
                    assert!(
                        !t.contains("hero"),
                        "`{prop}` reads the body height, which closes the binding loop: {t}"
                    );
                }
            }
        }
        assert!(seen >= 4, "the window no longer declares its size constants");

        // And the window's own four are still bound to the generated constants rather than to
        // anything the layout can influence.
        for want in [
            "min-width: Geometry.min-width;",
            "min-height: Geometry.min-height;",
            "preferred-width: Geometry.pref-width;",
            "preferred-height: Geometry.pref-height;",
        ] {
            assert!(
                window.lines().any(|l| l.trim() == want),
                "the window no longer declares `{want}`"
            );
        }
    }

    /// **T-5. The vertical axis is where the loop closes, so `root.height` is banned in markup.**
    ///
    /// The window's height comes from its layout, the layout from the content, the content from
    /// `hero` — so anything in the markup that reads the window's own height has closed it. Slint
    /// reports the inherited case as a **deprecation warning** saying it may panic at run time
    /// (`passes/binding_analysis.rs:359-362`, gated on a flag that defaults to false and that
    /// `slint-build` exposes no setter for), so the compiler will not fail the build and this is
    /// what does.
    ///
    /// **`root.width` is deliberately not banned.** The drawer pushes, so the well's width has to
    /// come from the window's; the horizontal axis has no pushed-in size the layout influences, and
    /// `min-width` / `preferred-width` are plain constants.
    #[test]
    fn nothing_in_the_markup_reads_the_windows_own_height() {
        for (name, text) in markup() {
            for (n, line) in text.lines().enumerate() {
                let t = strip(line);
                assert!(
                    !t.contains("root.height"),
                    "ui/{name}:{}: reads the window's own height, which closes the binding loop\n  \
                     {}",
                    n + 1,
                    line.trim()
                );
            }
        }
    }

    // ── The literal sweep, and the one exemption it carries ─────────────────────────────────────

    /// Properties whose value is a position, a size or a type measure.
    const GEOMETRY_PROPS: &[&str] = &[
        "x",
        "y",
        "width",
        "height",
        "min-width",
        "min-height",
        "preferred-width",
        "preferred-height",
        "border-radius",
        "font-size",
        "letter-spacing",
        "padding",
        "padding-left",
        "padding-right",
        "padding-top",
        "padding-bottom",
        "spacing",
        // `IPod`'s own size input. It is the one property in this markup whose value IS the body
        // height, and it was missing from this list — so `body-height: 655.751px` on a new use
        // site would have gone straight through the sweep that exists to stop exactly that.
        "body-height",
        // A border width is a size, and it was not in this list — so `border-width: 2px` on the
        // focus ring §7.3 asks for would have gone straight through the sweep that exists to stop
        // exactly that. `1px` stays in [`ALLOWED`] as a device-pixel hairline.
        "border-width",
        // §5's Scroll declares all four, and every one of them is a length or a position. They
        // arrive with the first `Flickable` in this markup, so they go in with it rather than
        // after somebody has written a number into one.
        "viewport-width",
        "viewport-height",
        "viewport-x",
        "viewport-y",
    ];

    /// Closed and exact. `0` and `0px` are nothing; `1px` is a device-pixel hairline, not a
    /// fraction of the body (`ipod.slint`'s two borders); `2` is the `/ 2` centring divisor;
    /// `100%` and `50%` are relative to the parent, which is what they are for; `420px` is
    /// `IPod`'s `body-height` **default**, which exists so `slint-viewer` and the live preview draw
    /// a plausible device with no Rust running — every real use site passes a size.
    const ALLOWED: &[&str] = &["0", "0px", "1px", "2", "100%", "50%", "420px"];

    // **There is no exemption list any more, and that is the retirement working rather than an
    // omission.**
    //
    // `CONTROL_METRICS` held `window.slint`'s twelve control metrics — sizes belonging to §6.2 and
    // §6.3, whose single source of truth is `Metric` in `ui/tokens.slint`, which item 9 does not
    // own. Eleven went when the chrome bar, the tab strip, the carousel and the caption stack were
    // deleted: `height: 36px;`, `border-radius: 6px;`, `height: 56px;`, `height: 60px;`,
    // `height: 20px;`, `height: 8px;`, `width: 7px;`, `height: 7px;`, `border-radius: 3.5px;`,
    // `spacing: 2px;` and `height: r.heading ? 44px : 30px;`.
    //
    // The twelfth was `height: 16px;` — §10's write-target row, kept at `label` size directly under
    // the device because deleting the caption stack before §7.5's shelf existed would have taken
    // with it the sentence standing between an afternoon and somebody's only image of an iPod they
    // own. Its stated retirement condition was *it becomes shelf row 3; then this list is empty and
    // goes*. It is shelf row 3 now (`ui/bench.slint`, at `Geometry.line-label`), so the list is
    // empty and it has gone, and `every_exemption_still_covers_a_line` — which existed to make the
    // list self-retiring — has gone with it. `no_geometry_literal_survives_in_the_markup` now sweeps
    // every markup file with no exemption at all.

    /// Strip string literals, then `//` comments, so neither can hide or invent a number.
    fn strip(line: &str) -> String {
        let mut out = String::new();
        let mut in_string = false;
        let mut chars = line.chars().peekable();
        while let Some(c) = chars.next() {
            match c {
                '"' => in_string = !in_string,
                '/' if !in_string && chars.peek() == Some(&'/') => break,
                _ if !in_string => out.push(c),
                _ => {}
            }
        }
        out
    }

    /// Every numeric literal in `text`, with its unit.
    ///
    /// Identifiers and colours are consumed **whole** first, because digits live inside both:
    /// `Metric.s7` is a name, `#ffffff14` is a colour, and — the one that actually bit —
    /// `Geometry.hero-phys-1x` is a name whose last two characters look exactly like a length. A
    /// hyphen is an identifier character in Slint, so scanning backwards one character is not
    /// enough to tell `hero-phys-1x` from `parent.height - 1px`.
    fn numbers(text: &str) -> Vec<String> {
        let b: Vec<char> = text.chars().collect();
        let mut out = Vec::new();
        let mut i = 0;
        while i < b.len() {
            let c = b[i];
            if c.is_alphabetic() || c == '_' {
                // An identifier: letters, digits, `_` and `-`, all the way to the end of it.
                while i < b.len() && (b[i].is_alphanumeric() || b[i] == '_' || b[i] == '-') {
                    i += 1;
                }
            } else if c == '#' {
                i += 1;
                while i < b.len() && b[i].is_alphanumeric() {
                    i += 1;
                }
            } else if c.is_ascii_digit() {
                let start = i;
                while i < b.len() && (b[i].is_ascii_digit() || b[i] == '.') {
                    i += 1;
                }
                while i < b.len() && (b[i].is_ascii_alphabetic() || b[i] == '%') {
                    i += 1;
                }
                out.push(b[start..i].iter().collect());
            } else {
                i += 1;
            }
        }
        out
    }

    /// One token of a markup file: an element opening, an element closing, or a statement.
    ///
    /// **Tokens rather than lines, and three exploitable holes are why.** The first cut classified a
    /// *line* by its trimmed prefix, so all three of these compiled and swept clean with a literal
    /// in them:
    ///
    /// ```text
    /// Rectangle { width: 37px; height: 13px; }     // an element body on one line
    /// states [ nudged when open : { handle.y: 37px; } ]   // a qualified target
    /// why => { root.spare = 37px; }                // an assignment inside a handler
    /// ```
    ///
    /// The first is the dangerous one: `Rectangle { width: 37px; }` is ordinary Slint that anybody
    /// writes without thinking, and this sweep exists to stop exactly that.
    #[derive(Debug, Clone, PartialEq)]
    enum Tok {
        /// The text before a `{`: `touch := TouchArea`, `if cond: Foo`, `clicked =>`.
        Open(usize, String),
        Close(usize),
        /// A `;`-terminated fragment, or whatever sat before a brace.
        Stmt(usize, String),
    }

    /// Split a markup file into [`Tok`]s. Comments and string bodies are removed first, so neither
    /// can hide or invent a number, and a wrapped binding is one statement rather than two lines.
    fn tokens(text: &str) -> Vec<Tok> {
        let mut out = Vec::new();
        let mut buf = String::new();
        // The line the buffer started on, so a wrapped statement is reported where it begins.
        let mut at = 1usize;
        let mut fresh = true;
        for (n, raw) in text.lines().enumerate() {
            let line = strip(raw);
            for c in line.chars() {
                match c {
                    '{' | '}' | ';' => {
                        let t = buf.trim().to_string();
                        if !t.is_empty() {
                            out.push(if c == '{' { Tok::Open(at, t) } else { Tok::Stmt(at, t) });
                        } else if c == '{' {
                            out.push(Tok::Open(at, String::new()));
                        }
                        if c == '}' {
                            out.push(Tok::Close(n + 1));
                        }
                        buf.clear();
                        fresh = true;
                    }
                    _ => {
                        if fresh && !c.is_whitespace() {
                            at = n + 1;
                            fresh = false;
                        }
                        buf.push(c);
                    }
                }
            }
            buf.push(' ');
        }
        let t = buf.trim().to_string();
        if !t.is_empty() {
            out.push(Tok::Stmt(at, t));
        }
        out
    }

    /// Every `property <length> NAME` declared anywhere in this markup.
    ///
    /// A declared length is geometry whatever it is called, so writing `root.spare = 37px` into a
    /// handler is caught by name. The set is global rather than per component, which makes it a
    /// superset and therefore strictly stricter — the point is that a number cannot get in.
    fn declared_lengths() -> std::collections::BTreeSet<String> {
        let mut out: std::collections::BTreeSet<String> = Default::default();
        for (_, text) in markup() {
            for tok in tokens(&text) {
                let (Tok::Stmt(_, t) | Tok::Open(_, t)) = tok else { continue };
                let Some(i) = t.find("property <length> ") else { continue };
                let rest = &t[i + "property <length> ".len()..];
                let name: String = rest
                    .chars()
                    .take_while(|c| c.is_alphanumeric() || *c == '-' || *c == '_')
                    .collect();
                if !name.is_empty() {
                    out.insert(name);
                }
            }
        }
        out
    }

    /// The value side of every geometry binding or assignment in one statement fragment.
    ///
    /// Matches `width:`, `handle.y:`, `root.spare =`, `property <length> foo:` — a property name,
    /// optionally qualified, followed by `:` or `=`.
    fn geometry_values(stmt: &str, extra: &std::collections::BTreeSet<String>) -> Vec<String> {
        let mut out = Vec::new();
        // A `property <length> foo: …` declaration is geometry whatever `foo` is called — that is
        // where `0.5917 * hero` used to live — so it is recognised by shape rather than by name.
        if let Some(i) = stmt.find("property <length> ") {
            if let Some(j) = stmt[i..].find(':') {
                out.push(stmt[i + j + 1..].to_string());
            }
        }
        out.extend(bound_values(stmt, |bare| {
            GEOMETRY_PROPS.contains(&bare) || extra.contains(bare)
        }));
        out
    }

    /// The value side of every binding or assignment in one statement whose property name `want`
    /// accepts.
    ///
    /// **One parser, two sweeps.** [`geometry_values`] and [`opacity_values`] ask different
    /// questions about the same grammar, and a second hand-rolled walk of `ident : value` is a
    /// second place for `Metric.s7`-is-not-a-7 to be got wrong. `the_literal_sweep_can_see_a_literal`
    /// is the control that keeps this honest for both of them.
    fn bound_values(stmt: &str, want: impl Fn(&str) -> bool) -> Vec<String> {
        let mut out = Vec::new();
        let bytes: Vec<char> = stmt.chars().collect();
        let is_ident = |c: char| c.is_alphanumeric() || c == '_' || c == '-' || c == '.';
        let mut i = 0;
        while i < bytes.len() {
            if i > 0 && is_ident(bytes[i - 1]) {
                i += 1;
                continue;
            }
            // Read an optionally-qualified identifier.
            let start = i;
            while i < bytes.len() && is_ident(bytes[i]) {
                i += 1;
            }
            if i == start {
                i += 1;
                continue;
            }
            let ident: String = bytes[start..i].iter().collect();
            // …then the separator.
            let mut j = i;
            while j < bytes.len() && bytes[j] == ' ' {
                j += 1;
            }
            // `==` is a comparison, not a binding.
            let binds = matches!(bytes.get(j), Some(':') | Some('='))
                && bytes.get(j + 1) != Some(&'=')
                && bytes.get(j.wrapping_sub(1)) != Some(&'=');
            if !binds {
                continue;
            }
            let bare = ident.rsplit('.').next().unwrap_or(&ident);
            if want(bare) {
                out.push(bytes[j + 1..].iter().collect());
            }
        }
        out
    }

    /// The value side of every `opacity` binding — including a declared one such as
    /// `material-opacity`, matched by suffix so a new name cannot slip the sweep.
    fn opacity_values(stmt: &str) -> Vec<String> {
        bound_values(stmt, |bare| bare == "opacity" || bare.ends_with("-opacity"))
    }

    /// **The closed set of opacities the markup is allowed to type**, each one cited.
    ///
    /// `opacity` is deliberately **not** in [`GEOMETRY_PROPS`]: it is not a position and not a size,
    /// and putting it there would force `0.55`, `0.82` and `0.86` into [`ALLOWED`] — where they
    /// would then silently permit `width: 0.55 * hero`, which is the one thing that sweep exists to
    /// stop. A narrower list for a narrower question keeps both strict.
    ///
    /// Everything here is a **cosmetic press or hold state**, decided in the drawing and belonging
    /// to it. [`GHOST_OPACITY`] is the other kind — a fraction the window computes and pushes — and
    /// it is deliberately absent, so `opacity: 0.45` cannot be written back into markup.
    const COSMETIC_OPACITIES: &[&str] = &[
        "0.0", // off — `ipod.slint`'s dark panel and unlit hold switch
        "1.0", // on, and the identity every ternary above returns to
        "0.55", // §7.4's four held wheel marks (`ipod.slint:343-373`)
        "0.82", // the held centre button (`ipod.slint:396`)
        "0.86", // §5's `Pressable` press state (`primitives.slint:453`)
    ];

    /// **T-20. The ghost's 45 % cannot be typed into the markup.**
    ///
    /// §10.1's ghost is a number the window decides — an emptiness state, pushed in — so it lives in
    /// [`GHOST_OPACITY`] and reaches the drawing as `Geometry.ghost-opacity`. A second copy typed
    /// into `ipod.slint` is the same defect a typed `0.5917` was, one property along, and the
    /// literal sweep does not cover it because `opacity` is not geometry.
    ///
    /// The cosmetic literals stay literals. That is the boundary, and it is the same one
    /// `ui/tokens.slint`'s type scale gets: a press state is the drawing's own decision; a fraction
    /// the program computes is not.
    #[test]
    fn no_opacity_literal_outside_the_cosmetic_set() {
        let mut seen = 0usize;
        for (name, text) in markup() {
            for tok in tokens(&text) {
                let (Tok::Stmt(n, stmt) | Tok::Open(n, stmt)) = tok else { continue };
                for value in opacity_values(&stmt) {
                    for num in numbers(&value) {
                        seen += 1;
                        assert!(
                            COSMETIC_OPACITIES.contains(&num.as_str()),
                            "ui/{name}:{n}: `{num}` is an opacity nobody declared. §10.1's ghost is \
                             `Geometry.ghost-opacity`; a cosmetic press state goes in \
                             COSMETIC_OPACITIES with the line that uses it\n  {stmt}"
                        );
                    }
                }
            }
        }
        // The control for the sweep's own reach, in the shape `AGENTS.md` §6 asks for: a sweep that
        // found no opacity at all looks exactly like one that found nothing wrong, and this markup
        // has fourteen of them.
        assert!(
            seen > 5,
            "the opacity sweep found {seen} literals in the whole markup, so it is reading nothing"
        );
    }

    /// **The control that makes the sweep above produce a non-zero.**
    #[test]
    fn the_opacity_sweep_can_see_a_literal() {
        let caught = |stmt: &str| -> Vec<String> {
            opacity_values(stmt)
                .iter()
                .flat_map(|v| numbers(v))
                .filter(|n| !COSMETIC_OPACITIES.contains(&n.as_str()))
                .collect()
        };

        // The exact line this sweep exists to refuse.
        assert_eq!(caught("opacity: root.ghost ? 0.45 : 1.0"), vec!["0.45".to_string()]);
        // …and the line it exists to permit.
        assert!(caught("opacity: root.ghost ? Geometry.ghost-opacity : 1.0").is_empty());
        // A declared one is matched by suffix, so a new name cannot slip it.
        assert_eq!(caught("in property <float> material-opacity: 0.45"), vec!["0.45".to_string()]);
        // The four real cosmetic states in this markup pass, or the sweep is refusing the drawing.
        for ok in [
            "opacity: screen-lit ? 1.0 : 0.0",
            "opacity: root.held-menu ? 0.55 : 1.0",
            "opacity: (centre-touch.pressed || root.held-select) ? 0.82 : 1.0",
            "opacity: root.material-opacity * (touch.pressed ? 0.86 : 1.0)",
        ] {
            assert!(caught(ok).is_empty(), "the sweep refuses a shipped cosmetic state: {ok}");
        }
        // `animate opacity { … }` is a block, not a binding, and carries no number of its own.
        assert!(caught("animate background, opacity").is_empty());
        // A property whose name merely CONTAINS the word is not one of them.
        assert!(caught("opacityish: 0.45").is_empty());
        // And the geometry sweep is not weakened by any of this: 0.55 is still a geometry literal.
        let none = std::collections::BTreeSet::new();
        assert_eq!(
            geometry_values("width: 0.55 * hero", &none)
                .iter()
                .flat_map(|v| numbers(v))
                .filter(|n| !ALLOWED.contains(&n.as_str()))
                .collect::<Vec<_>>(),
            vec!["0.55".to_string()],
            "putting `opacity` in GEOMETRY_PROPS would have had to allow 0.55 everywhere; that is \
             the trade this second sweep exists to avoid"
        );
    }

    /// **§10.1's ghost is a ghost.** A `GHOST_OPACITY` of 1.0 draws a solid iPod and every
    /// contrast assertion about it passes vacuously; one of 0 draws nothing and the bench is empty
    /// twice over.
    //
    // A declared constant checked against the range it has to be in, which is the point rather than
    // a defect; left as a run-time assertion so a failure names the value instead of stopping the
    // build. Same arrangement `the_drawer_fits_its_own_furniture_at_the_window_minimum` has.
    #[allow(clippy::assertions_on_constants)]
    #[test]
    fn the_ghost_opacity_is_a_fraction_and_is_emitted_as_one() {
        assert!(
            GHOST_OPACITY > 0.0 && GHOST_OPACITY < 1.0,
            "GHOST_OPACITY is {GHOST_OPACITY}; at 1.0 nothing is ghosted and at 0 nothing is drawn"
        );
        let (_, unit, value) = ALL
            .iter()
            .find(|(n, _, _)| *n == "GHOST_OPACITY")
            .expect("GHOST_OPACITY is emitted, or the markup cannot read it");
        assert_eq!(*unit, Unit::Ratio, "a fraction emitted as a length is `0.45px`");
        assert_eq!(*value, GHOST_OPACITY);
        assert!(
            slint_source().contains("out property <float> ghost-opacity: 0.45;"),
            "the generated global does not carry the ghost's opacity"
        );
    }

    /// **The hole this whole item exists to close.**
    ///
    /// After this test passes, editing the markup's geometry is not possible without editing
    /// `src/geometry.rs` — which is the mechanical form of "the test reads what the markup reads".
    ///
    /// **Whole statements, not lines.** A binding that wraps —
    ///
    /// ```text
    /// x: parent.width / 2 - self.width / 2
    ///  + (i - root.selected) * 88px;
    /// ```
    ///
    /// — puts its literal on a line that does not begin with a geometry property. And an element
    /// body written on one line puts three of them there. [`tokens`] splits on `;` and on braces, so
    /// neither shape is a line and both are swept.
    ///
    /// **There is no exemption any more.** The one that survived the bench rebuild was §10's
    /// `height: 16px;` write-target row, and it retired the moment that row became shelf row 3 — see
    /// the note where `CONTROL_METRICS` used to be.
    #[test]
    fn no_geometry_literal_survives_in_the_markup() {
        let extra = declared_lengths();
        for (name, text) in markup() {
            let file = format!("ui/{name}");
            for tok in tokens(&text) {
                let (Tok::Stmt(n, stmt) | Tok::Open(n, stmt)) = tok else { continue };
                // **`tokens.slint`'s own scale declarations are the one exemption, and it is a
                // boundary rather than a hole.** §16.9 gives *geometry* — positions and sizes — to
                // `src/geometry.rs`; §6.2's type scale and §6.3's space scale belong to `Metric`,
                // and this is where `Metric` is declared. `out property <length> s1: 4px;` IS the
                // single source of truth for that 4, and moving it to `geometry.rs` would put two
                // scales in one file with no rule separating them. Only the declaration form is
                // exempt: `x: 37px` in this file would still be caught, and `Metric.s1` at a use
                // site is a name rather than a number.
                if name == "tokens.slint" && stmt.contains("out property <length> ") {
                    continue;
                }
                for value in geometry_values(&stmt, &extra) {
                    for num in numbers(&value) {
                        assert!(
                            ALLOWED.contains(&num.as_str()),
                            "{file}:{n}: `{num}` is a geometry literal; it belongs in \
                             src/geometry.rs\n  {stmt}"
                        );
                    }
                }
            }
        }
    }

    /// **The control that makes the instrument produce a non-zero.**
    ///
    /// `AGENTS.md` §6: before believing a zero, run the control. The sweep above reports nothing,
    /// and a sweep that reports nothing because its matcher is broken looks exactly the same.
    ///
    /// The last three cases are the three shapes that were snuck past the previous, line-prefix
    /// matcher. Each of them compiles as ordinary Slint and each carried a literal the sweep exists
    /// to stop.
    #[test]
    fn the_literal_sweep_can_see_a_literal() {
        let none = std::collections::BTreeSet::new();
        // Everything the sweep would flag in one fragment, allowlist applied.
        let caught = |stmt: &str, extra: &std::collections::BTreeSet<String>| -> Vec<String> {
            geometry_values(stmt, extra)
                .iter()
                .flat_map(|v| numbers(v))
                .filter(|n| !ALLOWED.contains(&n.as_str()))
                .collect()
        };

        assert_eq!(caught("width: 0.5917 * h", &none), vec!["0.5917".to_string()]);
        assert_eq!(
            caught("property <length> hero: 655.751px", &none),
            vec!["655.751px".to_string()]
        );
        assert!(caught("background: #08080a", &none).is_empty());
        // `body-height` is the drawing's own size input, and it was not in the list.
        assert_eq!(caught("body-height: 655.751px", &none), vec!["655.751px".to_string()]);
        // A property whose name merely *starts* with one of them is not one of them.
        assert!(caught("heightish: 12px", &none).is_empty());
        // A comparison is not a binding.
        assert!(caught("visible: root.width == 12px", &none).is_empty());

        // `Metric.s7` is a name, not a 7; `#ffffff14` is a colour, not a 14; and
        // `Geometry.hero-phys-1x` is a name, not a `1x` — which the first version of this scanner
        // read as a literal, because a hyphen is an identifier character in Slint.
        assert!(caught("spacing: Metric.s7", &none).is_empty());
        assert!(caught("border-color: #ffffff14", &none).is_empty());
        assert!(caught("in property <length> hero: Geometry.hero-phys-1x", &none).is_empty());
        // …but a real subtraction of a real length still reads as one, and is allowed.
        assert_eq!(numbers("parent.height - 1px"), vec!["1px"]);
        assert!(caught("y: parent.height - 1px", &none).is_empty());
        assert!(caught("y: (parent.height - self.height) / 2", &none).is_empty());
        // A border width is a size, and the focus ring is the reason it had to be one. `1px` is an
        // allowed device-pixel hairline; the ring's own 2 is `Geometry.focus-ring-w` and typing it
        // is caught.
        assert!(caught("border-width: 1px", &none).is_empty());
        assert_eq!(caught("border-width: 2px", &none), vec!["2px".to_string()]);

        // ── The three that were snuck past the line-prefix matcher ──
        //
        // (a) An element body on one line. This is the dangerous one: ordinary Slint that anybody
        //     writes without thinking, and exactly what this sweep exists to stop.
        let one_line = tokens("Rectangle { width: 37px; height: 13px; background: Ink.line; }");
        let flagged: Vec<String> = one_line
            .iter()
            .filter_map(|t| match t {
                Tok::Stmt(_, s) | Tok::Open(_, s) => Some(s.clone()),
                Tok::Close(_) => None,
            })
            .flat_map(|s| caught(&s, &none))
            .collect();
        assert_eq!(flagged, vec!["37px".to_string(), "13px".to_string()]);

        // (b) A `states` block with a qualified target.
        assert_eq!(caught("handle.y: 37px", &none), vec!["37px".to_string()]);

        // (c) An assignment inside a callback handler, to a property declared elsewhere in the file.
        //     `spare` is not a geometry property by name; it is one because it was declared a
        //     `<length>`, which is what [`declared_lengths`] is for.
        let mut declared = std::collections::BTreeSet::new();
        declared.insert("spare".to_string());
        assert!(caught("root.spare = 37px", &none).is_empty());
        assert_eq!(caught("root.spare = 37px", &declared), vec!["37px".to_string()]);
        // …and the real markup does declare lengths, or that half is looking at nothing.
        assert!(
            !declared_lengths().is_empty(),
            "no `property <length>` was found in any markup file, so the by-name half of the \
             sweep is pointing at nothing"
        );
    }

    // ── The sweeps' own input, and the four fits the drawer has to survive ──────────────────────

    /// **T-1. Every markup file is swept, and the set is checked in both directions.**
    ///
    /// A sweep that names its own inputs stops sweeping the moment somebody adds a file — silently,
    /// and looking exactly like a sweep that found nothing. So the discovered set and the declared
    /// set are compared: a file on disk that nobody declared is unswept, and a declared file that
    /// is not on disk is a sweep pointing at nothing.
    #[test]
    fn every_markup_file_is_swept() {
        let found: Vec<String> = markup().into_iter().map(|(n, _)| n).collect();
        let mut want: Vec<String> = DECLARED_MARKUP.iter().map(|s| s.to_string()).collect();
        want.sort();

        let extra: Vec<&String> = found.iter().filter(|n| !want.contains(n)).collect();
        assert!(
            extra.is_empty(),
            "ui/ holds {extra:?}, which nothing in this module knows about — add it to \
             DECLARED_MARKUP or delete it"
        );
        let absent: Vec<&String> = want.iter().filter(|n| !found.contains(n)).collect();
        assert!(
            absent.is_empty(),
            "DECLARED_MARKUP names {absent:?}, which are not on disk — every sweep in this module \
             is pointing at nothing for them"
        );
    }

    /// **T-2. `Flickable` is declared in exactly one file, and it is never interactive.**
    ///
    /// §5's Scroll is the only element in the tree that declares one, so the whole of a
    /// `Flickable`'s cost is paid in one place and audited there. `interactive: false` is what
    /// retires §19.4's accepted 100 ms press latency —
    /// `Flickable::input_event_filter_before_children` returns `ForwardAndIgnore` for every
    /// non-wheel event when it is false, so `DelayForwarding(FORWARD_DELAY)` is never reached, and
    /// wheel events still fall through. The cost that replaces it is no touch-drag-to-flick.
    #[test]
    fn every_flickable_declares_itself_not_interactive() {
        let mut files: Vec<String> = Vec::new();
        for (name, text) in markup() {
            let lines: Vec<String> = text.lines().map(|l| strip(l).trim().to_string()).collect();
            for (n, line) in lines.iter().enumerate() {
                if !line.contains("Flickable") {
                    continue;
                }
                files.push(name.clone());
                // The declaration's own body: to the next `}` at the top of its nesting, which for
                // this element is short. Scanning the whole file would let a sibling's
                // `interactive: false` cover a Flickable that has none.
                let body: String = lines[n..].iter().take(24).cloned().collect::<Vec<_>>().join(" ");
                assert!(
                    body.contains("interactive: false;"),
                    "ui/{name}:{}: a Flickable that does not declare `interactive: false` costs \
                     every control inside it 100 ms of press latency\n  {line}",
                    n + 1
                );
            }
        }
        files.dedup();
        assert_eq!(
            files,
            vec!["primitives.slint".to_string()],
            "a Flickable is declared outside ui/primitives.slint; §5 has exactly one Scroll and \
             §16.11 bans nesting them"
        );
    }

    /// **T-3. The Rail never dismisses itself.**
    ///
    /// §14.4 bans the four-second self-dismissing message by name, and `Timer` **is** a real
    /// element in Slint 1.17 (`builtins.slint:2695`), so the ban is a live risk rather than a
    /// theoretical one. Two markup halves: no `Timer` anywhere, and no `animate` on a visibility in
    /// the Rail's own files. Markup read on purpose, like `the_generated_geometry_is_the_rust_one`
    /// — the thing being checked *is* the text.
    ///
    /// **The model half moved out of here**, into
    /// [`nothing_the_rail_says_changes_because_time_passed`], which watches the Rail instead of
    /// reading it; [`no_clock_is_named_anywhere_in_rail_rs`] is what is left of the grep and says
    /// so in its own name.
    #[test]
    fn the_rail_never_dismisses_itself() {
        for (name, text) in markup() {
            for (n, line) in text.lines().enumerate() {
                let t = strip(line);
                let t = t.trim();
                assert!(
                    !t.starts_with("Timer ") && !t.starts_with("Timer{") && !t.contains("Timer {"),
                    "ui/{name}:{}: a Timer. §14.4 bans the self-dismissing message by name\n  {}",
                    n + 1,
                    line.trim()
                );
                // **The animation ban is scoped to the Rail's own two files**, and deliberately so:
                // `ipod.slint` fades the drawn device's press feedback and `bench.slint` fades the
                // cradle, both of which are §8's motion working. What must never fade is an entry
                // that says something failed, out from under somebody reading it.
                if (name == "rail.slint" || name == "work.slint") && t.starts_with("animate ") {
                    let props = t.trim_start_matches("animate ");
                    for banned in ["visible", "opacity"] {
                        assert!(
                            !props.split(|c: char| !c.is_alphanumeric() && c != '-')
                                .any(|p| p == banned),
                            "ui/{name}:{}: animates `{banned}`, which is how a failure fades out \
                             from under somebody reading it\n  {}",
                            n + 1,
                            line.trim()
                        );
                    }
                }
            }
        }
    }

    /// A Rail holding one of every kind §9.2 has: a finished step, a step working against a byte
    /// count with a part-file behind it, a failed step, four still planned, and a note.
    fn a_rail_holding_one_of_everything() -> crate::rail::Rail {
        use eapp_loader::compose::{Holes, Loader, Os, Recipe, Start};

        let recipe = Recipe {
            start: Start::FromIpsw("iPod_25.1.3".into()),
            loader: Loader::Rockbox,
            oses: [Os::Apple, Os::Rockbox].into_iter().collect(),
        };
        let mut rail = crate::rail::Rail::new();
        let ids = rail.plan(&recipe.steps(Holes::Sparse));
        assert!(ids.len() >= 3, "the fixture filed {} steps", ids.len());
        rail.done(ids[0]);
        rail.progress(
            ids[1],
            crate::rail::Progress::Bytes {
                done: 4_100_000,
                total: 6_500_000,
            },
        );
        rail.writing(ids[1], std::path::PathBuf::from("/drives/mine.img.part"));
        rail.fail(
            ids[2],
            crate::rail::Failure::saying(
                crate::rail::Class::Verification,
                "fetching Rockbox",
                "the bytes do not match the checksum",
            ),
        );
        rail.note("Already making an iPod. The steps below are what it is doing.");
        // **And a failure with no step in front of it** — the centre button refusing. It is a
        // different producer from `fail`, which moves a planned step, and leaving it out is how the
        // first version of this test missed the very defect it was written for: the plant stamped
        // `note` and `failed`, the fixture exercised `fail`, and it passed.
        rail.failed(
            "making",
            "an iPod",
            crate::rail::Failure::new(
                crate::rail::Class::ToolMissing(crate::rail::Tool::Curl),
                "making an iPod",
            ),
        );
        rail
    }

    /// Everything a Rail hands the window — the entries themselves and every value derived from
    /// them, because a clock could be read in any of them.
    ///
    /// **One labelled line each rather than one string**, so a difference reports the one thing
    /// that moved instead of two screenfuls of `Debug` with a clause changed in the middle.
    fn everything_the_rail_says(r: &crate::rail::Rail) -> Vec<String> {
        let mut v = vec![
            format!("line: {:?}", r.line()),
            format!("announce: {:?}", r.announce()),
            format!("failures: {}", r.failures()),
            format!("entries: {}", r.entries().len()),
        ];
        for e in r.entries() {
            v.push(format!("entry {}: {e:?}", e.id));
            v.push(format!(
                "entry {} derived: fraction {} measure {:?} happened {:?} cancel {:?}",
                e.id,
                e.fraction(),
                e.measure(),
                e.happened(),
                e.cancel_cost()
            ));
        }
        v
    }

    /// Report the **first** line that moved, and say how many did.
    fn the_same_rail(before: &[String], after: &[String], how: &str) {
        for (b, a) in before.iter().zip(after.iter()) {
            assert_eq!(b, a, "{how}");
        }
        assert_eq!(before.len(), after.len(), "{how} — and it is a different number of entries");
    }

    /// **T-3b. Nothing on the Rail moves because time passed.** §14.4's four-second
    /// self-dismissing message, observed rather than spelled.
    ///
    /// **The grep this replaces was green through a working one.** Measured 2026-08-22: a
    /// `filed: Vec<(u64, u64)>` on `Rail`, stamped in `note` and `failed` from
    /// `eapp_loader::settings::now_unix()`, and a `line()` that skips an entry four seconds old —
    /// a failure fading off the bench out from under somebody reading it, which is precisely the
    /// thing §14.4 names — passed [`no_clock_is_named_anywhere_in_rail_rs`] and **all 342 tests in
    /// this crate**, because `now_unix` is not `std::time`, `Instant`, `SystemTime` or `Duration`.
    /// The clock a program reaches for is the one its own workspace already has.
    ///
    /// Two observations across one gap:
    ///
    /// * **The same Rail, read again.** Anything that expires, fades, ages or counts down has
    ///   moved by the time the second read happens.
    /// * **A second Rail, driven by the same calls.** Anything *stamped* into the model differs
    ///   between two runs separated by the gap — at nanosecond granularity because the two builds
    ///   are microseconds apart at least, and at second granularity because the gap crosses a
    ///   whole second. `Entry` is `PartialEq` and ids are minted per-Rail, so the twin is
    ///   comparable byte for byte.
    ///
    /// **The gap is four seconds and a fifth, and that number is the cost of this test.** It is
    /// §14.4's own number: this proves nothing expires *within four seconds*, which is the case the
    /// doctrine names and every shorter one. A longer timer than that is out of reach of any test
    /// that finishes, and is what [`no_clock_is_named_anywhere_in_rail_rs`] is still for. Sleeping
    /// longer than needed cannot make this pass — an entry that has already gone stays gone — so
    /// there is no flake here, only 4.2 s of wall clock in a binary that otherwise runs in 1.7.
    #[test]
    fn nothing_the_rail_says_changes_because_time_passed() {
        // §14.4's four seconds, and a fifth of one so the gap cannot land exactly on the boundary.
        const GAP: std::time::Duration = std::time::Duration::from_millis(4_200);

        let rail = a_rail_holding_one_of_everything();
        let before = everything_the_rail_says(&rail);
        // The fixture has to be worth watching: a Rail with nothing on it cannot lose anything.
        assert!(rail.line().is_some(), "the fixture puts no line on the bench");
        assert!(rail.failures() > 0, "the fixture holds no failure to dismiss itself");

        std::thread::sleep(GAP);

        the_same_rail(
            &before,
            &everything_the_rail_says(&rail),
            &format!(
                "the Rail said something different {} s later, with nothing having been asked of it",
                GAP.as_secs_f32()
            ),
        );

        let twin = a_rail_holding_one_of_everything();
        the_same_rail(
            &before,
            &everything_the_rail_says(&twin),
            &format!(
                "the same calls built a different Rail {} s later, so something in a Rail is \
                 stamped with the time it happened",
                GAP.as_secs_f32()
            ),
        );
    }

    /// **T-3c. No clock is named anywhere in `src/rail.rs`** — and this is a spelling lock, which
    /// is the whole of what it claims.
    ///
    /// **It cannot fail on behaviour.** It reads the file as text and asks which words are in it;
    /// a clock spelled a way this list does not know is invisible to it, which is exactly what
    /// happened — see [`nothing_the_rail_says_changes_because_time_passed`], which is the
    /// behavioural half and the one that watches the Rail. This is kept beside it because the two
    /// bound different things: that one proves nothing expires inside four seconds and cannot
    /// reach a longer timer; this one reaches any timer at all, and only if somebody spells it in
    /// the vocabulary below.
    ///
    /// **The vocabulary is the workspace's, not `std`'s.** The four words it used to hold were all
    /// `std::time`'s, and the clock nearest to hand here is
    /// [`eapp_loader::settings::now_unix`] — one `use` away, a whole second of granularity, and
    /// named by none of them. `parked_for` is its consumer and is on the list for the same reason.
    #[test]
    fn no_clock_is_named_anywhere_in_rail_rs() {
        const CLOCKS: [&str; 10] = [
            "std::time",
            "core::time",
            "Instant",
            "SystemTime",
            "Duration",
            "Timer",
            "now_unix",
            "parked_for",
            "elapsed",
            "sleep",
        ];
        let rail = include_str!("rail.rs");
        for word in CLOCKS {
            assert!(
                !rail.contains(word),
                "src/rail.rs names `{word}`; nothing in the Rail expires, so nothing in it needs \
                 a clock"
            );
        }
        // The control: the matcher can see one when there is one, so a matcher that found nothing
        // is not mistaken for a file that holds nothing.
        let planted = "self.filed.push((id, eapp_loader::settings::now_unix()));";
        assert!(
            CLOCKS.iter().any(|w| planted.contains(w)),
            "the vocabulary cannot see the clock this rule was written for"
        );
    }

    /// **T-6. The value column fits the drawer, and `PAGE_MARGIN` is still the space scale's 24.**
    ///
    /// Two halves and the second is the one that catches the duplication rather than the
    /// arithmetic: `PAGE_MARGIN` is the same number as `Metric.s5`, declared in two files because
    /// §6.3's scale is the markup's and §16.9's constants are Rust's, and the only thing stopping
    /// them drifting is that this reads one out of the other as text.
    //
    // **The identity is a tautology under the derivation, and it is kept for what that catches.**
    // `ROW_VALUE_W` is `DRAWER_W − 2 × PAGE_MARGIN − ROW_VALUE_X`, so the two columns sum to the
    // page's inner width by construction and moving `ROW_VALUE_X` cannot break it. What *does*
    // break it is somebody replacing the expression with a typed `140.0` — which is the second
    // source of truth this whole module exists to delete — and the moment they do, moving
    // `ROW_VALUE_X` goes red here. The check that can fail on today's numbers is the one under it.
    #[test]
    fn the_row_value_column_fits_the_drawer() {
        let inner = DRAWER_W - 2.0 * PAGE_MARGIN;
        let used = ROW_VALUE_X + ROW_VALUE_W;
        assert_eq!(
            used, inner,
            "the label and value columns are {used} wide inside a {inner} px page"
        );

        // Neither column may collapse. **Two Rows wide** is the floor, because §11.2 draws
        // two-word labels (`Which iPod`, `What it runs`) against two-word values (`Black 5.5G`,
        // `Apple + Rockbox`), and a column narrower than the row is tall cannot hold either.
        let floor = 2.0 * ROW_H;
        for (what, w) in [("label", ROW_VALUE_X), ("value", ROW_VALUE_W)] {
            assert!(
                w >= floor,
                "the {what} column is {w} px inside a {inner} px page; below {floor} it cannot \
                 hold the two-word {what}s §11.2 draws"
            );
        }

        let tokens = read("tokens.slint");
        let s5 = tokens
            .lines()
            .map(str::trim)
            .find_map(|l| l.strip_prefix("out property <length> s5: "))
            .and_then(|v| v.strip_suffix("px;"))
            .and_then(|v| v.parse::<f64>().ok())
            .expect("ui/tokens.slint declares s5");
        assert_eq!(
            s5, PAGE_MARGIN,
            "Metric.s5 is {s5}px and PAGE_MARGIN is {PAGE_MARGIN}; the drawer's page margin IS the \
             space scale's 24 and two spellings of one number is how they come to disagree"
        );
    }

    /// §6.2's `body` size has one source, and [`BODY_SIZE`] is the bounded duplicate of it.
    ///
    /// Same arrangement `the_row_value_column_fits_the_drawer` gives `Metric.s5` and
    /// [`PAGE_MARGIN`]: `ui/tokens.slint` owns the type scale, this file owns geometry, and the two
    /// numbers this file derives from a type size read the type size out of the markup as text.
    fn markup_body_size() -> f64 {
        read("tokens.slint")
            .lines()
            .map(str::trim)
            .find_map(|l| l.strip_prefix("out property <length> body-size: "))
            .and_then(|v| v.strip_suffix("px;"))
            .and_then(|v| v.parse::<f64>().ok())
            .expect("ui/tokens.slint declares body-size")
    }

    /// One of §6.3's closed space scale, out of `ui/tokens.slint`.
    ///
    /// [`RAIL_NEXT_W`] is derived from two of them, and a spacing token re-decided there has to move
    /// the column rather than leave a stale literal in this file — the arrangement [`PAGE_MARGIN`]
    /// already has with `s5`.
    fn markup_space(step: &str) -> f64 {
        let want = format!("out property <length> {step}: ");
        read("tokens.slint")
            .lines()
            .map(str::trim)
            .find_map(|l| l.strip_prefix(want.as_str()))
            .and_then(|v| v.strip_suffix("px;"))
            .and_then(|v| v.parse::<f64>().ok())
            .unwrap_or_else(|| panic!("ui/tokens.slint declares {step}"))
    }

    /// Every element in one markup file that binds `x:` — its name, and its own block's lines.
    ///
    /// The block is delimited by indentation rather than by brace matching: a `.slint` element is
    /// closed by a `}` outdented past the line that opened it, and every file in this tree is
    /// written that way. Cheap, and it fails loudly rather than quietly — a file that stops obeying
    /// it makes the control below stop finding anything.
    fn blocks_that_position_themselves(text: &str) -> Vec<Vec<String>> {
        let lines: Vec<&str> = text.lines().collect();
        let mut out: Vec<Vec<String>> = Vec::new();
        for (i, line) in lines.iter().enumerate() {
            if !line.trim_start().starts_with("x: ") {
                continue;
            }
            let indent = line.len() - line.trim_start().len();
            let mut block: Vec<String> = Vec::new();
            for later in &lines[i..] {
                let t = later.trim_start();
                if t == "}" && later.len() - t.len() < indent {
                    break;
                }
                block.push(t.to_string());
            }
            out.push(block);
        }
        out
    }

    /// **An `x` is not an inset**, and two pages had been drawn as though it were.
    ///
    /// A Slint layout sets each child's x **and** its width. Binding `x` overrides the first and
    /// leaves the second at the layout's own — so `x: Geometry.page-margin` on a wrapping `Text`
    /// moves it in at the leading edge and lets it run the same 24 px off the trailing one. It is
    /// invisible until a sentence is long enough to reach the edge, which is why it survived: on
    /// the Devices page the empty line is `No devices yet.` and never got there. On Parts it is
    /// §9.1's six paragraphs, and `_out/gui/parts-empty.png` had every one of them clipped by the
    /// window frame.
    ///
    /// The rule is narrow on purpose — a wrapping `Text` is the shape that shows the defect, and a
    /// `Pressable` positioned this way already carries an explicit width — so it fires on the thing
    /// that was actually wrong rather than on every absolute position in the tree.
    #[test]
    fn no_wrapping_paragraph_is_inset_at_one_edge_only() {
        let mut checked = 0usize;
        for (name, text) in markup() {
            for block in blocks_that_position_themselves(&text) {
                if !block.iter().any(|l| l.starts_with("wrap: word-wrap;")) {
                    continue;
                }
                checked += 1;
                assert!(
                    block.iter().any(|l| l.starts_with("width:")),
                    "ui/{name} positions a wrapping paragraph with `x` and never narrows it, so it \
                     is inset at the leading edge and overhangs the trailing one by the same \
                     amount:\n  {}",
                    block.join("\n  ")
                );
            }
        }
        assert!(
            checked >= 2,
            "the sweep found {checked} wrapping paragraphs positioned by `x`; it is reading \
             nothing and would pass over the defect it was written for"
        );
    }

    /// The control. A sweep that parses no blocks passes every file, and this one parses by
    /// indentation — so the thing worth proving is that it can still see a paragraph with no width.
    #[test]
    fn the_inset_sweep_can_see_a_paragraph_that_overhangs() {
        let bad = "        Text {\n            x: Geometry.page-margin;\n            \
                   text: root.empty-line;\n            wrap: word-wrap;\n        }\n";
        let blocks = blocks_that_position_themselves(bad);
        assert_eq!(blocks.len(), 1, "the block parser found {} blocks in one", blocks.len());
        assert!(
            blocks[0].iter().any(|l| l.starts_with("wrap: word-wrap;")),
            "the parser lost the `wrap` line, so the sweep would skip every paragraph"
        );
        assert!(
            !blocks[0].iter().any(|l| l.starts_with("width:")),
            "the parser reports a width in a block that has none, so the sweep can never fail"
        );
    }

    /// **§9.3's next-step pair is halves, and both of them carry the floor.**
    ///
    /// Three claims, each of which bites on its own:
    ///
    ///   1. **The constant is the half-share exactly.** `2 × RAIL_NEXT_W + s2` is the failure
    ///      block's inner width, so two floors and their gutter are the row and neither half can be
    ///      shrunk by its sibling. A floor below the share leaves the shrink free to squeeze; a
    ///      floor above it overflows the row. Both spacing terms are read out of `ui/tokens.slint`
    ///      as text, so re-deciding one moves this rather than leaving two numbers to disagree.
    ///   2. **Both controls carry it.** A constant no control carries is arithmetic about a page
    ///      that does not obey it, which is exactly what `ui/rail.slint` was — measured off
    ///      `_out/gui/work-failed.png`, a live `Retry` drew in 98 px beside a 194 px sibling.
    ///   3. **`REASON_MEASURE` is what is left of it.** The budget every reason in the program is
    ///      written to is this column less the control's own padding, and the two must not drift.
    #[test]
    fn the_next_step_column_is_the_half_share_of_the_row_it_is_in() {
        let (s2, s3) = (markup_space("s2"), markup_space("s3"));
        assert_eq!(
            2.0 * RAIL_NEXT_W + s2,
            REFUSAL_MEASURE - 2.0 * s3,
            "two {RAIL_NEXT_W} px halves and an {s2} px gutter are not the {} px the failure \
             block leaves; the halves either overflow the row or leave room the shrink can take",
            REFUSAL_MEASURE - 2.0 * s3
        );

        let markup = read("rail.slint");
        assert_eq!(
            markup.matches("min-width: Geometry.rail-next-w;").count(),
            2,
            "§9.3's next-step row draws two controls and {} of them carry the floor; the one that \
             does not is the one its sibling squeezes",
            markup.matches("min-width: Geometry.rail-next-w;").count()
        );

        assert_eq!(
            REASON_MEASURE,
            RAIL_NEXT_W - 2.0 * s3,
            "the reason budget is not this column less its own padding, so every sentence in the \
             program is written to a width nothing draws"
        );
    }

    /// Every verb the Rail can draw, **read out of `ui/rail.slint`'s own list** rather than out of a
    /// second copy here.
    ///
    /// `RailRow.verb`'s comment is the declaration — *fetch | build | copy | install | start |
    /// synthesise* — and it is the set the markup itself claims to draw. A seventh verb added there
    /// widens this automatically, which is the whole reason the list is not typed into this module.
    fn declared_verbs() -> Vec<String> {
        let text = read("rail.slint");
        let line = text
            .lines()
            .map(str::trim)
            .find(|l| l.starts_with("//") && l.contains("Step::verb()") && l.contains('|'))
            .expect("ui/rail.slint's RailRow.verb names the verbs it can draw");
        let list = line.rsplit('`').next().unwrap_or(line);
        let verbs: Vec<String> = list
            .split('|')
            .map(|v| v.trim().trim_end_matches('.').trim().to_string())
            .filter(|v| !v.is_empty() && v.chars().all(|c| c.is_ascii_lowercase()))
            .collect();
        assert!(
            verbs.len() >= 4,
            "only {verbs:?} parsed out of ui/rail.slint's verb list; the sweep is reading nothing"
        );
        verbs
    }

    /// **T-18. The Rail's verb column holds the longest verb this program can draw.**
    ///
    /// §17.Q12 named this as the one constant nobody had measured and predicted its failure exactly:
    /// *the longest verb is `synthesise` and it appears at first-run step 1, the first thing a new
    /// user ever sees this program do. If it elides, it elides there.* Phase 5 is what puts
    /// `synthesise` on screen, so the prediction becomes a test.
    ///
    /// **Still a budget, not a measurement.** [`BODY_ADVANCE`] is an estimate about a system UI face
    /// this program cannot interrogate — Slint 1.17 gives Rust no text-measurement API — so this
    /// bounds the column from below and says so. What it does mechanically is stop a seventh, longer
    /// verb from arriving without the column moving.
    #[test]
    fn the_rail_verb_column_holds_the_longest_verb() {
        let size = markup_body_size();
        assert_eq!(
            size, BODY_SIZE,
            "Metric.body-size is {size}px and geometry::BODY_SIZE is {BODY_SIZE}; the verb column \
             is derived from the type size and two spellings of one number is how they disagree"
        );

        let verbs = declared_verbs();
        let longest = verbs
            .iter()
            .max_by_key(|v| v.chars().count())
            .expect("at least one verb");
        let need = longest.chars().count() as f64 * size * BODY_ADVANCE;
        assert!(
            RAIL_VERB_W >= need,
            "`{longest}` needs about {need:.1} px at {size} px body and RAIL_VERB_W is \
             {RAIL_VERB_W}; it elides at first-run step 1, which is the first thing a new user \
             ever sees this program do"
        );

        // **Proof the budget can refuse something**, which is the only thing that makes it worth
        // having: the 64 px that shipped does not hold `synthesise`, and this is the arithmetic
        // that says so.
        const SHIPPED: f64 = 64.0;
        assert!(
            SHIPPED < need,
            "64 px was enough for `{longest}` after all, so widening the column bought nothing and \
             this check cannot fail"
        );

        // …and the column still leaves the subject line something to be. `what` carries
        // `horizontal-stretch: 1`, so it absorbs the widening — but not below nothing.
        let row = DRAWER_W - 2.0 * PAGE_MARGIN;
        let furniture = 16.0 + 8.0 + RAIL_VERB_W + 8.0;
        assert!(
            row - furniture >= 4.0 * ROW_H,
            "the verb column and its furniture leave {:.0} px for the subject inside a {row:.0} px \
             row",
            row - furniture
        );
    }

    /// **§7.3's cradle label budget is derived from the row it has to fit, and is a floor.**
    ///
    /// [`CRADLE_LABEL_MAX_CHARS`] is the expression rather than 48, so a re-measured
    /// [`BODY_ADVANCE`] moves every sentence that has to fit. This checks the derivation is the one
    /// the markup draws — `width: frame.width`, and the frame is the body plus a [`CRADLE_BAND`] a
    /// side — and that the budget is the *smallest* window's, which is the case worth refusing.
    #[test]
    fn the_cradle_label_budget_is_derived_from_the_row_it_has_to_fit() {
        let frame = BODY_ASPECT * HERO_PHYS_1X + 2.0 * CRADLE_BAND;
        let want = (frame / (BODY_ADVANCE * markup_body_size())) as usize;
        assert_eq!(
            CRADLE_LABEL_MAX_CHARS, want,
            "the budget is {CRADLE_LABEL_MAX_CHARS} characters and the {frame:.0} px row it has to \
             fit holds about {want}"
        );
        // A budget of zero, or of a whole paragraph, is a budget that refuses nothing.
        assert!(
            (24..=120).contains(&CRADLE_LABEL_MAX_CHARS),
            "{CRADLE_LABEL_MAX_CHARS} characters is not a sentence-sized budget"
        );
        // **The label is the cradle's, not the well's**, which is what makes `frame.width` the
        // right measure — see `ui/bench.slint`'s own note on why it moves with the frame's x.
        assert!(
            frame > BODY_ASPECT * HERO_PHYS_1X,
            "the label is measured against the body rather than against the fixture that holds it"
        );
    }

    /// **T-9. The drawer holds its own furniture at the window's declared minimum.**
    ///
    /// A page is a fixed header, a body, and a pinned footer. At [`MIN_HEIGHT`] the header and the
    /// footer are still their full size — nothing gives (§16.2) — so what is left over is the body,
    /// and it has to be at least [`DRAWER_MIN_BODY`] or the Work page has nowhere to put its first
    /// entry.
    //
    // Declared constants related to each other, which is the point rather than a defect; left as a
    // run-time assertion so a failure names the numbers instead of stopping the build.
    #[allow(clippy::assertions_on_constants)]
    #[test]
    fn the_drawer_fits_its_own_furniture_at_the_window_minimum() {
        let body = MIN_HEIGHT - SHELF - DRAWER_HEADER_H - WORK_FOOTER_H;
        assert!(
            body >= DRAWER_MIN_BODY,
            "at the window minimum the drawer has {body} px of body for a page that needs \
             {DRAWER_MIN_BODY} — {MIN_HEIGHT} minus {SHELF} shelf, {DRAWER_HEADER_H} header and \
             {WORK_FOOTER_H} footer"
        );
    }

    /// **T-10. The Composer's root fits the smallest window that draws the device at 1:1.**
    ///
    /// §11.2's three-groups-on-one-page came to about 1 090 px inside a drawer that is at most 803
    /// on the operator's own machine and 722 at the minimum, which is what forced the re-cut into
    /// three depth levels. This is that re-cut, checked: a header, three numbered rows, the
    /// always-reserved verdict, the plan and `Create`.
    ///
    /// The ceiling is derived rather than typed — `HERO_PHYS_1X + CHROME_MIN` is the client height
    /// a `k = 1` window needs, which is `fit::required_client_logical` written out, and the drawer
    /// is that less the shelf (§9.5's decision: only the shelf's three content rows narrow).
    ///
    /// **The page's own height is [`COMPOSER_ROOT_H`] and is no longer decomposed here.** It used
    /// to be, with a hand-typed `PLAN: f64 = 110.0` standing in for §11.2's drawing of the plan
    /// region and the pinned `Create` costing a bare `ROW_H` — two numbers this test owned that the
    /// markup would have had to reproduce, which is §16.9's rule broken inside the test that
    /// enforces it. The constant carries the derivation; this carries the bound.
    #[allow(clippy::assertions_on_constants)] // a declared total against a declared ceiling, which is the point; a run-time assert names both numbers where a `const` one names neither
    #[test]
    fn the_composer_root_fits_the_smallest_window_that_draws_the_device() {
        let ceiling = (HERO_PHYS_1X + CHROME_MIN) - SHELF;
        assert!(
            COMPOSER_ROOT_H <= ceiling,
            "the Composer's root is {COMPOSER_ROOT_H:.0} px inside a drawer that is {ceiling:.0} \
             at the smallest window that draws the device — §11.2's re-cut into three levels is \
             what this is supposed to buy"
        );
        // **§11.2's own stated minimum, which is stricter than the ceiling above.** *at most 803 px
        // on the operator's own machine and 722 at the minimum* — a measurement of a display class
        // rather than a constant of this program, so it is written here with the sentence it comes
        // from rather than declared in `geometry.rs` as though the program decided it.
        let stated = 722.0 - SHELF;
        assert!(
            COMPOSER_ROOT_H <= stated,
            "the Composer's root is {COMPOSER_ROOT_H:.0} px and §11.2's stated 722 px window \
             leaves {stated:.0} for the drawer. It fits the device-at-1:1 ceiling and not the \
             window the design is written against, which is the case that matters"
        );
        // And the shape it replaced does not fit, or the re-cut bought nothing.
        assert!(
            1090.0 > ceiling,
            "the three-groups-on-one-page shape was ~1090 px and this says it fits in \
             {ceiling:.0}; the check is dead"
        );
    }

    /// **§11.2's level ① fits the same drawer, and the locked case is what it costs.**
    ///
    /// §11.1's *existing and new look identical* is a height claim before it is anything else: a
    /// locked picker stays a picker and a locked `Field` keeps its two-line slot, so all four
    /// identity controls are `ROW_H + FIELD_REASON` whichever kind of ROM is chosen. That is 312 px
    /// of the 548, and it is the reservation that stops the surface jumping when you switch between
    /// a retail dump and a synthesised iPod.
    ///
    /// It is checked against §11.2's stated 722 px window rather than against the device-at-1:1
    /// ceiling, because that is the smaller of the two and the one the design is written against.
    #[allow(clippy::assertions_on_constants)] // same arrangement as the test above: a run-time assert names both numbers
    #[test]
    fn the_composers_first_level_fits_the_drawer_at_the_stated_minimum() {
        let stated = 722.0 - SHELF;
        assert!(
            LEVEL_ONE_H <= stated,
            "level ① is {LEVEL_ONE_H:.0} px inside a drawer that is {stated:.0} at §11.2's stated \
             minimum"
        );
        // **The reservation is the whole cost, and this is what says so.** Collapsing the locked
        // Model / Colour / Serial / GUID to bare rows would save 4 × FIELD_REASON — and buy a page
        // that changes shape depending on which kind of ROM you chose, which §11.1 refuses.
        let collapsed = LEVEL_ONE_H - 4.0 * FIELD_REASON;
        assert!(
            collapsed < LEVEL_ONE_H,
            "the reason slot costs nothing, so §11.1's identical-heights rule is free and this \
             test is measuring nothing"
        );
    }

    /// **§11.4's preview glass is [`bezel_phys`] at `k = 1`, not a second measurement of it.**
    ///
    /// §6.1's geometric tell is the black surround, and a preview that drew its own would be the
    /// drawn iPod's bezel and the previewed iPod's bezel disagreeing on the same page.
    #[test]
    fn the_preview_glass_is_the_bezel_at_one_to_one() {
        assert_eq!(
            PREVIEW_GLASS,
            bezel_phys(),
            "PREVIEW_GLASS is {PREVIEW_GLASS} and the drawn bezel is {}; one of the two was typed",
            bezel_phys()
        );
    }

    /// **The drawer's ROOT page does not fit the drawer, and that is why it scrolls.**
    ///
    /// `the_drawer_fits_its_own_furniture_at_the_window_minimum` checks the *furniture* — header,
    /// shelf, footer — and says nothing about what a page puts between them. `MenuPage` puts seven
    /// rows there, six of them disabled, and a disabled `Pressable` is `ROW_H + FIELD_REASON` = 78
    /// because §9.4's reason slot is reserved under it. That is 556 px inside a drawer that is 312
    /// at the declared window minimum: Work cut in half, and Readout / Settings / Reference entirely
    /// outside a `clip` that no `Flickable` can recover them from.
    ///
    /// So this asserts both halves of the answer: the page genuinely does not fit, and it declares a
    /// `Scroll`. Dropping either — a shorter page or a lost Scroll — is a page whose bottom rows are
    /// unreachable by pointer, by keyboard and by an assistive technology at once.
    #[test]
    fn the_drawers_root_page_needs_more_room_than_it_has_and_therefore_scrolls() {
        let text = read("drawer.slint");
        let rows = text.matches("count: 7;").count();
        assert_eq!(rows, 7, "`MenuPage` no longer declares seven rows of seven: {rows}");
        let disabled = text.matches("enabled: false;").count();
        // **Two, and it was three, and before that six.** Devices, Parts, Settings and now the
        // Readout became live as `ui/drawer.slint` gained a child for each; `Page::slot` answers
        // `None` for exactly Games and Reference. The count is read out of the markup and the
        // arithmetic below is derived from it, so the next page to land moves both — and the page
        // still needs more room than it has, which is the claim this test is actually about.
        assert_eq!(disabled, 2, "`MenuPage` no longer has two disabled rows: {disabled}");

        let needed = DRAWER_HEADER_H
            + disabled as f64 * (ROW_H + FIELD_REASON)
            + (rows - disabled) as f64 * ROW_H;
        let have = MIN_HEIGHT - SHELF;
        assert!(
            needed > have,
            "the root page needs {needed:.0} px and has {have:.0} at the window minimum, so it \
             fits and the Scroll below is unnecessary. Delete this test rather than the Scroll."
        );

        // The whole page's own three cells, in the order they have to be in: a fixed header, then
        // the Scroll. `WorkPage` had this right; the root page of the same drawer did not.
        let menu = text
            .split_once("export component MenuPage")
            .expect("ui/drawer.slint declares MenuPage")
            .1
            .split_once("export component Drawer")
            .map_or_else(|| text.clone(), |(a, _)| a.to_string());
        assert!(
            menu.contains("DrawerHeader"),
            "`MenuPage` has no header, so there is no way out of it in the same place as every \
             other page"
        );
        assert!(
            menu.contains("Scroll {"),
            "`MenuPage` needs {needed:.0} px inside {have:.0} and declares no Scroll — its last \
             three rows are outside the drawer's clip, which is not a Flickable, so they are out \
             of the tab order and out of the accessible tree with no indicator that they exist"
        );
        assert!(
            menu.matches("ensure-visible").count() == rows,
            "not every row brings itself into view when the keyboard reaches it; Tab is the only \
             keyboard scroll route this program has (§16.11)"
        );
    }

    // ── Accessibility and glyphs: two sweeps whose failure is silent without them ────────────────

    /// **T-18. No `accessible-*` property is set without a constant role on the same element.**
    ///
    /// Slint's accessibility lowering (`lower_accessibility.rs:29-33`) says **nothing** when an
    /// element sets `accessible-label` beside `AccessibleRole.none` — the label simply never
    /// reaches anybody. A role behind a ternary is worse: it is a compile error in one direction
    /// and a silent nothing in the other, which is why the spelling is checked here as well.
    ///
    /// **It walks [`Tok`]s rather than lines.** The line-prefix version could not see an element
    /// written on one line — `Rectangle { accessible-role: AccessibleRole.none; accessible-label:
    /// "…"; }` was neither an open, a close nor a binding, and fell through all three. That is the
    /// one case this test uniquely catches, since a conditional role and an orphan label are both
    /// compile errors on their own, so the hole was the whole of the test.
    #[test]
    fn no_accessible_property_is_set_without_a_constant_role() {
        let bearers = role_bearing_components();
        // The control: a component that declares one has to be in the set, or the set is empty and
        // every use site below is being waved through.
        assert!(
            bearers.contains("Pressable"),
            "no component in this markup was found to declare a constant accessible-role, so the \
             sweep below cannot tell a role-bearing element from any other: {bearers:?}"
        );

        for (name, text) in markup() {
            let toks = tokens(&text);
            // A stack of open elements. Each frame remembers whether a role reaches it — its own
            // binding, its element type's, or an ancestor's — because §16.7 accepts a role on the
            // element or on the one containing it.
            let mut stack: Vec<bool> = vec![false];
            // Every element whose role arrives AFTER a binding it has to cover, so the order the
            // language does not require is not required here either. Recorded as we go and checked
            // once the element closes.
            let mut pending: Vec<(usize, String)> = Vec::new();
            let mut frames: Vec<usize> = vec![0];

            for tok in &toks {
                match tok {
                    Tok::Open(_, head) => {
                        let inherited = *stack.last().unwrap_or(&false);
                        stack.push(inherited || bearers.contains(&element_type(head)));
                        frames.push(pending.len());
                    }
                    Tok::Close(_) => {
                        let covered = stack.pop().unwrap_or(false);
                        let from = frames.pop().unwrap_or(0);
                        if covered {
                            pending.truncate(from);
                        }
                    }
                    Tok::Stmt(n, stmt) => {
                        let Some(rest) = stmt.strip_prefix("accessible-") else {
                            continue;
                        };
                        // `accessible-action-default => { … }` is a **callback**, not a property,
                        // and a callback needs no role to be legal. Only bindings are swept.
                        if rest.contains("=>") {
                            continue;
                        }
                        if let Some(v) = rest.strip_prefix("role:") {
                            assert!(
                                !v.contains('?'),
                                "ui/{name}:{n}: a conditional accessible-role. It must be a \
                                 constant\n  {stmt}"
                            );
                            // **The silent one.** `AccessibleRole.none` beside a label compiles,
                            // says nothing (`lower_accessibility.rs:29-33`) and reaches nobody.
                            assert!(
                                !v.contains("AccessibleRole.none"),
                                "ui/{name}:{n}: AccessibleRole.none on an element that carries \
                                 other accessible-* bindings — the label reaches nobody\n  {stmt}"
                            );
                            if let Some(top) = stack.last_mut() {
                                *top = true;
                            }
                            pending.truncate(*frames.last().unwrap_or(&0));
                        } else {
                            // §16.7's own abbreviation does not compile: the properties are
                            // `accessible-item-index` / `-count`, not `accessible-index` / `-count`.
                            for wrong in ["index:", "count:"] {
                                assert!(
                                    !rest.starts_with(wrong),
                                    "ui/{name}:{n}: `accessible-{wrong}` is not a property; it is \
                                     `accessible-item-{wrong}`"
                                );
                            }
                            if !*stack.last().unwrap_or(&false) {
                                pending.push((*n, stmt.clone()));
                            }
                        }
                    }
                }
            }
            if let Some((n, stmt)) = pending.first() {
                panic!(
                    "ui/{name}:{n}: `{stmt}` with no accessible-role on the element or on anything \
                     containing it"
                );
            }
        }
    }

    /// **Every duration comes from the `Motion` global, and `lively` has exactly one use site.**
    ///
    /// §8.4's reduced motion is one multiplication inside one global, so a use site writes
    /// `Motion.gentle` and cannot forget it. A hard-coded `duration: 200ms;` is therefore a silent
    /// reduced-motion hole that nothing else in this program would see — which is the precise
    /// failure mode the pre-multiplied global was chosen to prevent, and nothing was checking it.
    ///
    /// The second half is §8's table read literally: *`lively` — drawer page depth **only**, nothing
    /// else, ever.* `lively` is `ease-out-back` and overshoots, and §8.2 rule 2 forbids an
    /// overshooting curve anywhere near a property the Screen's geometry reads.
    #[test]
    fn every_duration_is_a_motion_token_and_lively_has_one_use_site() {
        let mut durations = 0usize;
        let mut lively: Vec<String> = Vec::new();
        for (name, text) in markup() {
            for tok in tokens(&text) {
                let (Tok::Stmt(n, stmt) | Tok::Open(n, stmt)) = tok else { continue };
                let Some(v) = stmt.strip_prefix("duration:") else { continue };
                durations += 1;
                assert!(
                    v.contains("Motion."),
                    "ui/{name}:{n}: a duration that is not a `Motion` token. §8.4's reduced-motion \
                     multiplication lives inside that global, so a literal here is an animation \
                     that keeps running with reduce-motion on and no test would see it.\n  {stmt}"
                );
                if v.contains("Motion.lively") {
                    lively.push(format!("ui/{name}:{n}"));
                }
            }
        }
        // The control: a sweep that found no durations at all would pass both assertions.
        assert!(durations > 5, "only {durations} `duration:` bindings were found in the markup");
        assert_eq!(
            lively.len(),
            1,
            "`Motion.lively` is used at {lively:?}. §8's table: drawer page depth ONLY, nothing \
             else, ever — it overshoots, and §8.2 rule 2 keeps an overshooting curve away from \
             anything the Screen's geometry reads"
        );
        assert!(
            lively[0].starts_with("ui/drawer.slint"),
            "`Motion.lively`'s one use site moved off the drawer's depth strip: {lively:?}"
        );
    }

    /// **Every markup file is reachable from the one compile root, or it is exempt and says why.**
    ///
    /// `build.rs` hands the Slint compiler exactly one root (`ui/window.slint`) and must keep
    /// exactly one `compile*` call — a second clobbers `SLINT_INCLUDE_GENERATED` and `MainWindow`
    /// stops existing. So a file nothing imports is compiled by nothing: a syntax error or a binding
    /// loop in it fails no build. That gap had a test of its own while `bench.slint` was unimported;
    /// the test retired on schedule and the hole re-opened one file over with nothing naming it.
    #[test]
    fn every_markup_file_is_reachable_from_the_compile_root() {
        // `preview.slint` is a second top-level `Window` for `slint-viewer`, and it imports the
        // components it draws rather than being imported. Its own discipline is
        // `tests/markup_discipline.rs`, which reads it as text.
        const NOT_A_COMPILE_INPUT: &[&str] = &["preview.slint"];

        let mut reached: std::collections::BTreeSet<String> = Default::default();
        let mut queue = vec!["window.slint".to_string()];
        while let Some(f) = queue.pop() {
            if !reached.insert(f.clone()) {
                continue;
            }
            let Some((_, text)) = markup().into_iter().find(|(n, _)| *n == f) else { continue };
            for line in text.lines() {
                let t = line.trim();
                if !t.starts_with("import ") && !t.starts_with("export {") {
                    continue;
                }
                let Some(open) = t.find('"') else { continue };
                let Some(close) = t[open + 1..].find('"') else { continue };
                let target = &t[open + 1..open + 1 + close];
                if target.ends_with(".slint") {
                    queue.push(target.to_string());
                }
            }
        }
        // The control: the walk has to have gone somewhere.
        assert!(
            reached.len() > 3,
            "the import walk reached {reached:?}, which is not a graph — it is reading nothing"
        );

        let orphans: Vec<String> = markup()
            .into_iter()
            .map(|(n, _)| n)
            .filter(|n| !reached.contains(n) && !NOT_A_COMPILE_INPUT.contains(&n.as_str()))
            .collect();
        assert!(
            orphans.is_empty(),
            "{orphans:?} are compiled by nothing — `build.rs` gives the Slint compiler one root and \
             nothing imports these, so a syntax error or a binding loop in them fails no build"
        );
    }

    /// The control for the sweep above, fed the shape that used to walk straight through it.
    #[test]
    fn the_accessible_sweep_can_see_a_one_line_element() {
        let one = "Rectangle { accessible-role: AccessibleRole.none; accessible-label: \"x\"; }";
        let toks = tokens(one);
        assert_eq!(
            toks.len(),
            4,
            "an element body on one line is an open, two statements and a close: {toks:?}"
        );
        assert!(matches!(&toks[0], Tok::Open(_, h) if h == "Rectangle"));
        assert!(
            matches!(&toks[1], Tok::Stmt(_, s) if s.starts_with("accessible-role:")),
            "the role binding on a one-line element is not a statement: {:?}",
            toks[1]
        );
        assert!(matches!(&toks[3], Tok::Close(_)));
    }

    /// The element type on a line that opens a block: `touch := TouchArea {` is a `TouchArea`.
    fn element_type(line: &str) -> String {
        let head = line.trim_end_matches('{').trim();
        let head = head.rsplit(":=").next().unwrap_or(head).trim();
        head.split_whitespace().next_back().unwrap_or("").to_string()
    }

    /// Every component in this markup whose own declaration sets a constant `accessible-role`,
    /// transitively through `inherits`.
    ///
    /// **Without this the sweep cannot see a `Pressable`'s role from its use site.** `Pressable`
    /// declares `accessible-role: AccessibleRole.button` once; every use site sets a label and a
    /// description and no role, which is correct and is the whole point of having the component.
    fn role_bearing_components() -> std::collections::BTreeSet<String> {
        let mut bearers: std::collections::BTreeSet<String> = Default::default();
        let mut inherits: Vec<(String, String)> = Vec::new();

        for (_, text) in markup() {
            let lines: Vec<String> = text.lines().map(|l| strip(l).trim().to_string()).collect();
            let mut current: Option<String> = None;
            let mut depth = 0usize;
            for line in &lines {
                if let Some(rest) = line
                    .strip_prefix("export component ")
                    .or_else(|| line.strip_prefix("component "))
                {
                    let mut it = rest.split_whitespace();
                    let name = it.next().unwrap_or("").to_string();
                    if it.next() == Some("inherits") {
                        if let Some(base) = it.next() {
                            inherits.push((name.clone(), base.trim_end_matches('{').to_string()));
                        }
                    }
                    current = Some(name);
                    depth = 0;
                }
                if line.ends_with('{') {
                    depth += 1;
                }
                if line.starts_with('}') {
                    depth = depth.saturating_sub(1);
                    if depth == 0 {
                        current = None;
                    }
                }
                // Depth 1 is the component's own root; anything deeper is a child of it.
                if depth == 1 && line.starts_with("accessible-role:") {
                    if let Some(c) = current.clone() {
                        bearers.insert(c);
                    }
                }
            }
        }

        // `Row inherits Pressable` carries `Pressable`'s role. Fixpoint, because the chain can be
        // any length.
        loop {
            let before = bearers.len();
            for (name, base) in &inherits {
                if bearers.contains(base) {
                    bearers.insert(name.clone());
                }
            }
            if bearers.len() == before {
                break;
            }
        }
        bearers
    }

    // `role_later_in_this_element` used to live here — a forward line scan for a role declared after
    // a binding it covers. The token walk above holds the same bindings in `pending` until the
    // element closes, which answers the same question without a second parser, so it is deleted
    // rather than left standing (§16.9).

    /// **The closed set of non-ASCII characters allowed in a string the window draws.**
    ///
    /// §16.6: Slint takes one `font-family` per element with no fallback list, and a missing glyph
    /// falls to `.notdef` — the empty square. Nothing in `.slint` can ask whether a glyph exists,
    /// so the only mechanism available is a closed set that a person has decided on.
    ///
    /// Each of these is present in the system UI face on every platform this program runs on, and
    /// each earns its place in prose this document is written in. **A character not on this list is
    /// a decision, not an oversight** — §6.7's answer for a symbol is that it is drawn as a `Path`,
    /// not typed. Do not add one to make a test pass.
    /// **The line is punctuation versus symbol**, and it is drawn where §6.7 draws it. A symbol —
    /// `·`, `×`, `›` — is *drawn as a `Path`*, which `ui/bench.slint` does for the shelf's own MENU
    /// list. A punctuation mark is text and stays text. `·` and `×` used to be on this list, and
    /// were the two the shelf drew as Paths one row below where Rust typed them.
    const GLYPHS: &[char] = &[
        '—', // em dash — the sentence break this program's prose is built on
        '…', // ellipsis — one glyph rather than three full stops
        '§', // a section reference
    ];

    /// Macros whose string argument reaches a **terminal**, not a `Text`.
    ///
    /// `IPOD_LAYOUT`'s box-drawing rule and every panic message land in whatever font the operator's
    /// terminal is set to, which this program neither chooses nor can ask about. The closed set
    /// above speaks for the window's own font and for nothing else.
    const TERMINAL: &[&str] = &[
        "eprintln!",
        "println!",
        "eprint!",
        "print!",
        "panic!",
        "unreachable!",
        "assert",
        ".expect(",
    ];

    /// The net change in parenthesis depth on one line, ignoring anything inside a string literal.
    ///
    /// It is what lets the terminal filter above span the lines a `println!` invocation actually
    /// occupies. Without it the filter is per line, and the format string of a wrapped `println!`
    /// is not on the line the macro's name is on.
    fn unquoted_parens(line: &str) -> i32 {
        let mut depth = 0i32;
        let mut in_string = false;
        let mut escaped = false;
        for c in line.chars() {
            if in_string {
                if escaped {
                    escaped = false;
                } else if c == '\\' {
                    escaped = true;
                } else if c == '"' {
                    in_string = false;
                }
                continue;
            }
            match c {
                '"' => in_string = true,
                '(' => depth += 1,
                ')' => depth -= 1,
                _ => {}
            }
        }
        depth
    }

    /// **The model's own sources — `eapp-loader`'s library, and not its command-line programs.**
    ///
    /// §6.7's rule is about a glyph rendered by *this program's* font. Half the sentences that font
    /// is asked to draw are not written in this crate at all: `inspect::flash`'s verdict, the fact
    /// lists behind every Parts row, `nor::Source::describe` and every `Provenance` line are worded
    /// in `eapp-loader` and rendered here verbatim. Four of them joined their lists with U+00B7 and
    /// nothing looked, because this sweep read `tools/ipod-gui/src` and that is the other crate.
    ///
    /// **The line is the crate's own shape.** `src/*.rs` is the library the window links; a
    /// function in it can be handed to a `Text` tomorrow whether or not one is today. `src/bin/*.rs`
    /// is a `main` that owns a terminal, in whatever font the operator set, which this program
    /// neither chooses nor can interrogate — so those are excluded, by not recursing into the
    /// directory rather than by a list that would have to be maintained.
    ///
    /// The exclusion is real rather than nominal: `bin/trace.rs` prints `✅` and `⚠️`, and
    /// `bin/ipod-boot.rs` still joins with `·`. Both are correct where they are, and both would
    /// fail this sweep if it read them. What the library costs is nothing — after the four
    /// sentences were reworded there is not one non-ASCII character left in any string literal it
    /// ships, outside the three the window's font is trusted for.
    ///
    /// The cut is `#[cfg(test)]` at the start of a line, not `mod tests {`: that crate names its
    /// test modules `naming_tests`, `syscfg_tests`, `figure_tests` and a dozen other things, and
    /// `lib.rs` has no module called `tests` at all — so the window's own rule would have swept
    /// 9 300 lines of `lib.rs` including its tests, and `settings.rs` planted middle dot with them.
    fn model_sources() -> Vec<(String, String)> {
        let dir =
            std::path::PathBuf::from(concat!(env!("CARGO_MANIFEST_DIR"), "/../eapp-loader/src"));
        let mut out: Vec<(String, String)> = std::fs::read_dir(&dir)
            .unwrap_or_else(|e| panic!("{}: {e}", dir.display()))
            .flatten()
            .map(|e| e.path())
            .filter(|p| p.extension().is_some_and(|x| x == "rs"))
            .map(|p| {
                let name = p.file_name().unwrap().to_string_lossy().into_owned();
                let text = std::fs::read_to_string(&p).expect("a source file");
                let kept: Vec<&str> = text
                    .lines()
                    .take_while(|l| !l.starts_with("#[cfg(test)]"))
                    .collect();
                (name, kept.join("\n"))
            })
            .collect();
        out.sort();
        // The control on the cut: it must not have taken the shipped half with it. `lib.rs` is the
        // machine and `nor.rs` is where a sentence this sweep exists for is worded.
        assert!(
            out.iter()
                .any(|(n, t)| n == "lib.rs" && t.contains("pub fn step")),
            "the test cut removed the model"
        );
        assert!(
            out.iter()
                .any(|(n, t)| n == "nor.rs" && t.contains("pub fn synthesise")),
            "the test cut removed the ROM synthesiser"
        );
        out
    }

    /// **T-19. No UI string carries a glyph outside that set — in the markup, in this crate's Rust,
    /// or in the model's.**
    ///
    /// Comments are stripped first, so the prose above every one of these files does not count —
    /// only what the window actually draws.
    ///
    /// **Three halves, and two of them were ungated in turn.** §6.7's own wording is *"no source
    /// file may contain a non-ASCII character rendered as UI text"*, and it names ` · ` (U+00B7) as
    /// the character the shipped window built into UI strings with no coverage gate at all. The
    /// first widening added this crate's `src/*.rs`, because `ui/*.slint` carries almost no prose
    /// and every sentence the bench and the Rail draw is built in Rust. That left the *model*: four
    /// sentences worded in `eapp-loader` and drawn here verbatim, joining their lists with the very
    /// character §6.7 names. `parts.rs` substituted a comma for them at its own boundary, which
    /// covered one page and left every other caller drawing empty squares. See [`model_sources`].
    #[test]
    fn no_ui_string_carries_a_glyph_outside_the_closed_set() {
        let (mut markup_files, mut window_files, mut model_files) = (0usize, 0usize, 0usize);
        // `rust_sources` cuts each file at its own test module, so this sweeps what the program
        // ships rather than what its tests write down. It lives beside the sweeps that first needed
        // it (`main.rs`), and there is one of it rather than two.
        let files = markup()
            .into_iter()
            .map(|(n, t)| (format!("ui/{n}"), t))
            .chain(
                crate::tests::rust_sources()
                    .into_iter()
                    .map(|(n, t)| (format!("src/{n}"), t)),
            )
            .chain(
                model_sources()
                    .into_iter()
                    .map(|(n, t)| (format!("eapp-loader/src/{n}"), t)),
            );
        for (name, text) in files {
            match name.split('/').next() {
                Some("ui") => markup_files += 1,
                Some("src") => window_files += 1,
                _ => model_files += 1,
            }
            // **A string that goes to a terminal is not UI text.** §6.7's rule is about a glyph
            // rendered by *this program's* font, in a `Text` whose family it chose and cannot
            // interrogate. `IPOD_LAYOUT`'s box-drawing rule and a panic message land in whatever
            // font the operator's terminal is set to.
            //
            // The depth counter is what makes that work rather than nearly work: `println!(` and
            // its format string are usually on **different lines**, so a per-line check waved
            // through six `µ`s in `emu.rs` and would have gone on doing so.
            let mut depth = 0i32;
            for (n, line) in text.lines().enumerate() {
                // Rust doc comments are prose about the program, not strings the program draws.
                if line.trim_start().starts_with("//") {
                    continue;
                }
                if depth == 0 && TERMINAL.iter().any(|m| line.contains(m)) {
                    // Balanced on one line → 0, and this line is skipped either way.
                    depth = unquoted_parens(line).max(0);
                    continue;
                }
                if depth > 0 {
                    depth = (depth + unquoted_parens(line)).max(0);
                    continue;
                }
                for s in string_literals(line) {
                    for c in s.chars() {
                        assert!(
                            c.is_ascii() || GLYPHS.contains(&c),
                            "{name}:{}: the string carries `{c}` (U+{:04X}), which is not in \
                             the closed set this program's font is trusted for. §6.7's answer for \
                             a symbol is a drawn Path — do not widen the list to make this \
                             pass.\n  {}",
                            n + 1,
                            c as u32,
                            line.trim()
                        );
                    }
                }
            }
        }
        // The control for the sweep's own reach: it has to have seen all three halves, and a sweep
        // that found nothing looks exactly like a set that carries nothing.
        assert_eq!(
            markup_files,
            DECLARED_MARKUP.len(),
            "the markup half read {markup_files} files and there are {}",
            DECLARED_MARKUP.len()
        );
        assert!(window_files > 5, "the window half read {window_files} files");
        assert!(model_files > 15, "the model half read {model_files} files");
    }

    /// Every string literal on one line, comments excluded.
    ///
    /// The mirror of [`strip`], which keeps everything a string is not; this keeps everything a
    /// string is. Both walk the line the same way, so a `//` inside a string is not a comment in
    /// either of them.
    fn string_literals(line: &str) -> Vec<String> {
        let mut out = Vec::new();
        let mut current = String::new();
        let mut in_string = false;
        let mut chars = line.chars().peekable();
        while let Some(c) = chars.next() {
            match c {
                '"' => {
                    if in_string {
                        out.push(std::mem::take(&mut current));
                    }
                    in_string = !in_string;
                }
                '/' if !in_string && chars.peek() == Some(&'/') => break,
                _ if in_string => current.push(c),
                _ => {}
            }
        }
        out
    }

    /// The control: the scanner can see a glyph, and it does not read one out of a comment.
    #[test]
    fn the_glyph_sweep_can_see_a_glyph() {
        assert_eq!(
            string_literals(r#"text: "Press ▓ to start"; // a ▓ in a comment"#),
            vec!["Press ▓ to start".to_string()]
        );
        assert!(string_literals("// nothing but a \u{2593} comment").is_empty());
        assert!(!GLYPHS.contains(&'▓'), "the set was widened to include a block element");
        // …the punctuation the prose is written in is on the list rather than tripping it…
        for c in ['—', '…', '§'] {
            assert!(GLYPHS.contains(&c), "`{c}` is used in this program's own prose");
        }
        // …and the two SYMBOLS the shelf draws as `Path`s are not, because one band cannot have two
        // answers to one question. §6.7 names `·` as the character the shipped window built into UI
        // strings with no coverage gate at all.
        for c in ['·', '×', '›'] {
            assert!(
                !GLYPHS.contains(&c),
                "`{c}` is a symbol, and §6.7's answer for a symbol is a drawn Path — ui/bench.slint \
                 draws this one"
            );
        }
    }
}
